programs.sol:
"""Sparse line-start and code-syntax approximation.

Unspaced A--D get an early-line negative pulse that fades with line count;
repeated initials also weaken B--D.  E--F have weaker pulses.  Blank-line
openings are small and positive; A is also positive away from line starts.
Answer gets a large negative pulse following several early A--D line openings.
PHP's opening tag and Python's constructor definition get separate negative
pulses.  Other tokens are quiet.  State resets at document boundaries.
"""
READS = ()
INITIALS = 'ABCDEF'


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, lines, seen, choices, position, tail = '', 0, {}, 0, 0, ''
    else:
        _, previous, lines, seen, choices, position, tail = carry

    value = 0.08 if text == 'A' else 0.0
    if position == 0 and text == 'A':
        value = 0.54
    if previous.endswith('\n'):
        blank = previous.count('\n') > 1
        if text in INITIALS and len(text) == 1:
            if text == 'A':
                value = 0.17 if blank else 0.15 - 1.73 / lines
            elif text in 'BCD':
                value = 0.04 if blank else (
                    0.20 - 1.50 / (lines ** 0.5 * (1 + seen.get(text, 0)))
                )
            else:
                value = 0.03 if blank else (
                    0.10 - 0.55 / (lines * (1 + seen.get(text, 0)))
                )
            if text in 'ABCD':
                choices += 1
        elif text == 'Answer':
            if blank:
                value = 0.25
            else:
                value = -2.0 if choices >= 2 and lines <= 8 else -0.4

    if text == 'php' and previous.endswith('<?'):
        value = -3.32 if position == 1 else -0.9
    if text == 'init' and tail.endswith('def __'):
        value = -0.99

    if len(text) == 1 and text in INITIALS:
        seen[text] = seen.get(text, 0) + 1
    return (
        doc, text, lines + text.count('\n'), seen, choices,
        position + 1, (tail + text)[-32:]
    ), float(value)

programs.haiku:
"""Layer 1, MLP down_proj, component 4545: a quiz answer-letter detector.

What it does
- Goes negative on the bare option letter A, B, C or D that starts a line right after a
  single newline, as in a multiple-choice list ("...?\\nA. ...\\nB. ..."). The bigger the
  drop when the letter comes early in its document, where a quiz is most likely to sit
  near the top of the page. Later in a long document the dip fades.
- Negative on a few other line-start cue words: "Answer" (as in "Answer: C"), "init" in
  "__init__", and "php" after "<?".
- Slightly positive on the first token of each document (the mean is about +0.09, but
  the sign and size depend on the particular token, which a short rule cannot capture).
- Everywhere else it predicts 0. The real activation there is small noise (std ~0.05).

Measured on training rows: it explains only a few percent of the variance. Most of the
variance is token-specific noise that no short rule captures.
"""

READS = ()

OPTION_LETTERS = ("A", "B", "C", "D")


def _line_start(prev):
    """The previous token ends a line with one newline (not a blank line)."""
    return prev.endswith("\n") and not prev.endswith("\n\n")


def _option_value(position):
    """How far an option letter pushes the activation down, by its position in the document."""
    if position < 40:
        return -1.1
    if position < 80:
        return -0.6
    if position < 160:
        return -0.35
    return -0.17


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.09  # first token of a document
    prev = prefix.token_strings[-2]
    if token in OPTION_LETTERS and _line_start(prev):
        return carry, _option_value(prefix.position)
    if token == "Answer" and _line_start(prev):
        return carry, -1.0
    if token == "init" and prev.endswith("__"):
        return carry, -0.35
    if token == "php" and prev == "<?":
        return carry, -2.0
    return carry, 0.0

programs.sol:
"""A lexical quantity/count signal, not an arithmetic counter.

Specific counts and count-variable names are positive, especially their
'of' complements. Vague quantities are weak; mathematical kinds of number
are negative. Only a short recent-text buffer supplies phrase/code context.
"""
import re

READS = ()
QUANTITY = r'(?:number|amount|quantity|numero|número|nombre|anzahl)'
VAGUE = {'a', 'large', 'certain', 'considerable', 'small', 'huge', 'great'}
NUMBER_TYPES = {
    'even', 'odd', 'prime', 'complex', 'real', 'positive',
    'negative', 'integer', 'rational',
}
COUNT_PREFIX = r'(?<!\\)(?:\b|_)(n|num|nb|nr)$'


def last_word(text):
    m = re.search(r'(\w+)\W*$', text)
    return m[1] if m else ''


def predict(old, token):
    before = old.lower()
    word = token.strip().strip('._-([{,=').lower()
    prev = last_word(before)
    if word in {'of', 'de'}:
        if re.search(r'\bno\.\s*$', before):
            return 4.0
        m = re.search(r'\b' + QUANTITY + r'\s*$', before)
        if m:
            left = before[:m.start()].rstrip()
            if last_word(left) in VAGUE | NUMBER_TYPES:
                return 0.3
            if re.search(r'[#"=]\s*$|\bint\)?\s*:?$', left):
                return 4.5
            return 2.4 if last_word(left) == 'the' else 1.9
        if re.search(COUNT_PREFIX, before):
            return 5.0

    # Count-name prefixes, then plural-looking or dimension-name suffixes.
    prefix = re.search(COUNT_PREFIX, before)
    camel = (token[:1].isupper() and not token.isupper() and
             (old.endswith('n') or (prefix and prefix[1] != 'n')))
    if prefix and (token.startswith('_') or camel):
        noun = token.strip('_')
        plural = (noun.endswith('s') and not noun.endswith(('ss', 'us'))
                  and noun not in {'plus', 'minus'})
        dimension = noun.lower() in {'row', 'col', 'dim', 'pts'}
        return 2.8 if plural or dimension or noun.isupper() else 0.6
    if word == 'n':
        if old.endswith('\\'):
            return -0.04  # Escaped newline, not a numeric variable.
        if token in {'n', 'N'} and old and old[-1].isalpha():
            return 0.0
        if re.search(r'\b(?:int|long|size_t|uint\d*_t)\s*$', before):
            return 3.0
        code = re.search(r'[=;{}]|\b(?:int|range|len|size|import)\b', old[-100:])
        return (0.8 if token[:1].isspace() else 0.4) if code else 0.3
    if not old.endswith('\\') and re.fullmatch(
            r'(?:num|nb|nr|n)[A-Z_]\w+|nrows|ncols', token.strip().lstrip('.')):
        return 3.0
    if word in {'num', 'cnt', 'nr', 'nb'}:
        return 1.7
    if re.fullmatch(QUANTITY, word):
        if prev in NUMBER_TYPES:
            return -0.9
        if prev in VAGUE:
            return 0.1
        if prev in {'total', 'maximum', 'minimum', 'expected'}:
            return 1.7
        if re.search(r'[#"=]\s*$', before):
            return 1.1
        if prev == 'the':
            return 0.35 if word == 'amount' else 0.8
        return 0.3
    if word in {'count', 'counts', 'counter', 'counting'}:
        return 0.6
    if word == 'total':
        return 0.2 if token[:1].isspace() else 0.6
    if word == 'many':
        return 0.9 if prev == 'how' else 0.06
    if word in {'id', 'ids'}:
        return 0.3
    if token.strip() in {
        '数', '数量', '人数', '次数', '个数', '总数', '页数', '条数',
    }:
        return 0.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(old, token) - (0.1 if not old else 0.0)
    return (doc, (old + token)[-150:]), value

programs.haiku:
"""Quantity / "how many" detector for layers.1.mlp.down_proj:4546.

The component reads the current token and the one before it. It fires when the
text is talking about a count of things:

* the "of" right after the count words "number", "amount", "count" (about 1.9; about
  3 when capitalised, as in "Number of" or "No. of"), and a weaker "of" after a few
  measure nouns ("fraction", "size", "length", "speed", ...);
* the count words themselves, weakly (about 0.2);
* in code, the shorthand count variables: a bare n or num used as a variable
  (`i < n`, `(num`, `int n`, `self.n`) about 1.1, and "nb" about 0.8;
* the suffix that completes a shorthand: `n` + `_nodes`, `num` + `_rows` (about 2.2),
  `num` + `Channels` (weaker, about 0.15).

Everything else predicts 0. Values are the mean activation of each rule's cases on
about 4000 training rows.
"""
READS = ()

COUNT_HEADS = {"number", "amount", "numero", "numer", "no", "count", "nombre"}
COUNT_SHORT = {"num", "n", "nb"}
CODE_WORDS = {"self", "int", "return", "for", "long", "size", "const"}
CODE_PUNCT = {"<", "(", "((", ",", ";", "`", "`,", "=", "$", "."}
MEASURE_OF = {"fraction", "percentage", "proportion", "size", "length", "speed",
              "velocity", "density", "majority", "degree"}


def _letters(s):
    """Lowercase letters of a token, e.g. ' Number' -> 'number', '"No.' -> 'no'."""
    return "".join(c for c in s if c.isalpha()).lower()


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    if len(toks) < 2:
        return None, 0.0
    cur, prev = toks[-1], toks[-2]
    w_cur, w_prev = _letters(cur), _letters(prev)
    if cur.strip() in ("of", "OF", "de"):
        if w_prev in COUNT_HEADS:
            return None, 3.0 if prev.strip()[:1].isupper() else 1.9
        if w_prev in MEASURE_OF:
            return None, 0.25
        return None, 0.0
    if w_prev in COUNT_SHORT and cur[:1] == "_":
        return None, 2.2
    if w_prev in COUNT_SHORT and cur[:1].isupper():
        return None, 0.15
    if w_cur == "nb":
        return None, 0.8
    if w_cur in ("n", "num") and cur.strip() == cur.strip().lower():
        if prev.strip() in CODE_PUNCT or w_prev in CODE_WORDS:
            return None, 1.1
    if w_cur in COUNT_HEADS or w_cur in COUNT_SHORT:
        return None, 0.18
    return None, 0.0

programs.sol:
"""A sparse response to formatting and orthographic variants.

Unfamiliar tabs, long-s, fi/fl ligatures and British spellings give
negative values. Repetition within a document weakens these responses.
Chat delimiters have fixed offsets; document-initial text has its own baseline.
This is a selective approximation: ordinary lexical variation is left at zero.
"""
import re
from functools import lru_cache
import opencc

READS = ()

BRITISH = re.compile(
    r'(?:colour|favour|labour|neighbour|honour|behaviour|flavour|harbour)'
    r'|(?:recognis|organis|realis|personalis|authoris|criticis)'
    r'(?:e|ed|es|ing|ation|ations)?$'
    r'|analys(?:e|ed|ing)$'
    r'|(?:(?:kilo|centi|milli)?metre|litre|centre|theatre|defence|licence)'
    r'|(?:manoe|whilst)|programmes?$|is(?:ed|ing|ation|ations)$'
    r'|(?:fulfil|enrol)(?:$|ment)'
)
CHAT = {
    '<|im_start|>': .13, '<|im_end|>': .09,
    '<think>': -.13, '</think>': -.40,
    '<tool_call>': -.12, '</tool_call>': .03,
    '<tool_response>': .11, '</tool_response>': -.10,
}
SIMPLIFY = opencc.OpenCC('t2s')


@lru_cache(8192)
def variant_inside(s):
    """Traditional variants of the Chinese locative character 里."""
    return not s.isascii() and any(
        ch != '里' and SIMPLIFY.convert(ch) == '里' for ch in s
    )


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, {}, 0)
    _, pos, counts, tabs = carry
    s = prefix.token_strings[-1]
    word = s.strip()
    seen = counts.get(s, 0)
    value = 0.0

    if pos == 0:
        if word.isalpha():
            value = .25 if s[:1].isspace() else .35
        elif s == ' ':
            value = -.18
        elif not word:
            value = .5
            if s.strip(' ') == '' and 2 <= len(s) <= 6:
                value = 1.1
            elif s == '\t':
                value = 1.4
        elif not word.isdigit():
            value = .1
    elif s in CHAT:
        value = CHAT[s]
    elif '\t' in s:
        density = (tabs + seen) / (pos + 100)
        if s.strip():
            density = (tabs + seen) / (pos + 30)
            value = .04 - .38 / (1 + 100 * density)
        elif s.count('\t') > 1:
            value = .05 - .21 / (1 + 300 * tabs / (pos + 100))
        elif ' ' in s:
            value = .12 - .65 / (1 + 100 * density)
        else:
            value = .06 - .50 / (1 + 300 * density)
    elif '\xa0' in s:
        value = .09 - .17 / (1 + 150 * seen / (pos + 100))
    elif s == '   ':
        value = -.07 / (1 + 60 * seen / (pos + 30))
        bracketed = prefix.token_strings[-2].endswith(']')
        if bracketed:
            value = -.35
    elif s == '    ':
        value = -.05
    elif 'ſ' in s:
        value = .27 - .81 / (1 + 150 * seen / (pos + 100))
    elif any(ch in s for ch in 'ﬁﬂ'):
        value = -.6 / (1 + 100 * seen / (pos + 100))
    elif BRITISH.match(word.lower()):
        value = (-.05 if word[:1].isupper() else -.25)
        value /= 1 + 1000 * seen / (pos + 100)
    elif variant_inside(s):
        value = -.65 / (1 + 100 * seen / (pos + 100))

    counts[s] = seen + 1
    return (doc, pos + 1, counts, tabs + ('\t' in s)), value

"""A sparse approximation to source-code declaration openings.

Positive rules recognize import braces, wildcards, static imports, declaration
names and Go import indentation. Negative rules recognize imported Python
utilities and quoted Go package names. Source formatting changes the gain.
A separate rule recognizes a document-initial "Title:" label. Other positions
predict zero: ordinary lexical background and fine name-specific effects are
not modeled. State resets at document boundaries.
"""
import re
import sys

READS = ()

# Common language/platform namespaces, not imported application identifiers.
JAVA_ROOTS = {
    'java', 'javax', 'org', 'com', 'android', 'androidx', 'kotlin', 'lombok',
}
SCIENTIFIC = {
    'numpy', 'pandas', 'scipy', 'matplotlib', 'torch', 'tensorflow',
    'keras', 'skimage', 'pygame', 'tqdm',
}
PYTHON_CLIENTS = {'requests', 'pytest', 'serial', 'click', 'google'}
NODE_MODULES = {'fs', 'path', 'express', 'router', 'http', 'https'}

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0, False, False)
    _, prev, line, n, escaped, go = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    previous = prev.strip().lstrip('+-')
    value = 0.0
    numbered = bool(re.match(r'^\s*\d+\s*[:\t ]', line))
    gain = 0.6 if escaped else (0.65 if numbered else 1.0)
    if prev.startswith('\t') and not numbered:
        gain *= 0.65
    direct_import = (
        previous == 'import' and not re.search(r'\bfrom\b', line)
    )

    if direct_import:
        if word.startswith('{'):
            value = (15.6 if n == 1 and prev == 'import' else 9.0) * gain
        elif word.startswith('*'):
            value = 4.2 * gain
        elif word == 'static':
            value = 2.7 * gain
        elif word.startswith('('):
            value = 0.65 if escaped or numbered else 1.15
            go = True
        elif word.startswith(('"', "'")):
            value = -0.7
            go = 'single'
        elif token[:1].isspace() and word.isidentifier():
            if word in JAVA_ROOTS:
                value = -0.2
            elif word in SCIENTIFIC or word in {'os', 'sys', 'json', 'math', 'io'}:
                value = -0.2
            elif word in sys.stdlib_module_names or word in PYTHON_CLIENTS:
                strong = word in {'random', 'time', 'tempfile'} or 'test' in word
                value = -2.4 if strong else -1.4
            elif word == 'net':
                value = 0.8
            elif word in {'Data', 'Control', 'System'}:
                value = 2.8 * gain
            elif re.match(r'^\s*(?:[+\-]|\d+[\s:]+)?\s*import$', line):
                value = (1.5 if word[0].isupper() else 0.8) * gain

    # Named imports can follow a default import or the TypeScript "type" modifier.
    if word.startswith('{') and not direct_import:
        if re.search(r'\bimport\s+(?:\w+\s*,|type)\s*$', line):
            value = (15.6 if n <= 3 else 8.5) * gain

    if previous in {'const', 'var', 'let'}:
        unindented = not prev[:1].isspace()
        if word == '{':
            spaced = unindented and token.startswith(' ')
            value = (5.0 if spaced else 0.55) * gain
        elif token.startswith(' ') and word.isidentifier():
            if word in NODE_MODULES:
                value = (2.7 if unindented else 0.0) * gain
            elif unindented and len(word) > 2 and word[0].islower():
                value = 0.35 * gain

    # Go import entries: indentation and the beginning of a quoted module path.
    if go:
        if token == '\t' and line == '':
            value = 4.0
        before = re.sub(r'\\[nt]', ' ', line).strip()
        opening = re.match(r'^\s*"([A-Za-z]+)', token)
        separate = (
            before.endswith('"')
            and not re.search(r'"[^"]*[A-Za-z]', before)
        )
        if opening or (separate and re.match(r'^[A-Za-z]', token)):
            name = opening[1] if opening else re.match(r'[A-Za-z]+', token)[0]
            if name in {'testing', 'reflect', 'sync'}:
                value = -3.8
            elif name in {'fmt', 'time', 'sort'}:
                value = -2.9 * (0.6 if opening else 1.0)
            elif name in {'context', 'errors', 'bytes', 'strings'}:
                value = -2.1 * (0.6 if opening else 1.0)
            else:
                value = -0.3
        if word.startswith(')'):
            go = False

    if n == 1 and previous == 'Title' and word == ':':
        value = 3.98

    # Keep only the current logical source line, not a growing decoded prefix.
    line += token
    if '\n' in token:
        line = line.rsplit('\n', 1)[-1]
        escaped = False
        if go == 'single':
            go = False
    if '\\n' in line:
        line = line.rsplit('\\n', 1)[-1]
        escaped = True
    return (doc, token, line[-240:], n + 1, escaped, go), float(value)

"""A phrase-internal AND detector, not a general punctuation detector.

Coordinating conjunctions usually give a negative value; a preceding comma
largely cancels it. English values also use the previous word's spelling and
dictionary word classes. Word-internal 'and' has the opposite sign, and Boolean
AND in an if/while/assert expression is treated separately. Short function-word
cues distinguish Romance conjunctions from mathematical variables and citations.
Only a short text tail is retained, resetting at each document boundary.
"""
import re
from functools import lru_cache
import wordnet

READS = ()

CONJUNCTIONS = {
    'and': -2.8, 'und': -2.95, 'и': -2.1, 'og': -2.6,
    'och': -2.6, 'và': -1.5, 'dan': -2.0, 'és': -2.0,
    've': -1.0, 'și': -1.1,
}
LANGUAGE_CUES = {
    'y': set('el la los las del que por para con una un se su es como'.split()),
    'e': set(('il lo gli della delle nel alla che non uma os as dos das '
              'do da que para com não em').split()),
    'et': set('le la les du des une un dans pour avec est aux au qui que'.split()),
    'en': set('het een van voor met zijn niet dit deze wordt worden als'.split()),
}
ENGLISH = set('the of to and is are that this with for was were'.split())
GERMAN = set('der die das ein eine einer nicht mit von zu den dem ist ich wir'.split())
FUNCTION_WORDS = set(
    'a an the of to for in on at by with as from into over than that this '
    'these those it is are was were be been being have has had can could '
    'will would should may might must not no if or but and'.split()
)


@lru_cache(maxsize=20000)
def word_classes(word):
    return wordnet.parts_of_speech(word.lower())


def english_phrase(previous, tail):
    """Estimate the strength of coordination after a word."""
    lower = previous.lower()
    pos = word_classes(previous)
    value = -2.04 - 0.52 * min(len(previous), 15) / 10
    value += 0.77 * previous.istitle() - 0.49 * previous.isupper()
    value += 0.67 * (lower in FUNCTION_WORDS)
    value -= 0.53 * ('noun' in pos)
    value += 0.28 * ('adjective' in pos) + 0.28 * ('adverb' in pos)
    value -= 0.35 * lower.endswith('s')
    value -= 0.09 * lower.endswith('ed')
    value += 0.2 * lower.endswith('ing')
    value += 0.35 * bool(re.search(r'\band\b', tail[-50:]))
    return value


def english_and(s, tail):
    if not tail:
        return 0.36 if s.startswith(' ') else 0.67
    last = tail.rstrip()[-1:]
    if not last:
        return 0.3
    if last == ',':
        return -0.06
    if last == ';':
        return 0.85
    if last == ':':
        return 0.6
    if last in '!?':
        return 0.1
    if s == 'and':
        if tail[-1:].isalpha():
            return 2.5
        return -1.9 if tail[-1:].isspace() else -0.7
    line = tail.rsplit('\n', 1)[-1]
    if re.search(r'\b(if|elif|while|assert|return)\s', line):
        if re.search(r'[_=<>\[\]()]', line) or line.lstrip().startswith(
                ('if ', 'elif ', 'while ', 'assert ', 'return ')):
            return 0.8
    words = re.findall(r'[^\W\d_]+', tail.lower())
    if sum(w in GERMAN for w in words) >= 2 and not any(w in ENGLISH for w in words):
        return 1.8
    m = re.search(r'([^\W\d_]+)$', tail)
    if m:
        return english_phrase(m[1], tail)
    if last == '.':
        return -1.0
    if last.isdigit():
        return -2.2
    if last in ')]}':
        return -2.4
    return -1.8


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    word = s.strip()
    boundary = s[:1].isspace() or tail[-1:].isspace()
    value = 0.0
    if word == 'and':
        value = english_and(s, tail)
    elif s == 'und' and tail[-1:].isalpha():
        value = 0.6
    elif word in {'And', 'AND'}:
        value = 0.25 if s.startswith(' ') or word == 'And' else 0.8
    elif word == '-and':
        value = 0.9
    else:
        strength = CONJUNCTIONS.get(word) if boundary else None
        if word in LANGUAGE_CUES and boundary:
            words = re.findall(r'[^\W\d_]+', tail.lower())
            cues = sum(w in LANGUAGE_CUES[word] for w in words)
            english = sum(w in ENGLISH for w in words)
            strength = -2.7 if cues >= 2 and cues > english else None
        if word.endswith('和'):
            strength = -2.2
        if strength is not None:
            last = tail.rstrip()[-1:]
            if not tail:
                value = 0.0
            elif last and last in ',;:!?，、；：':
                value = 0.1
            else:
                value = strength
    return (doc, (tail + s)[-240:]), value

"""A sparse, case-sensitive phrase detector, with a few opening-token effects.

Negative pulses mark web-page labels and formulaic English constructions
(apologies, certainty questions, dates and task instructions). Completing
Chinese 真主 (Allah) gives a positive pulse. Most other tokens get zero.
A small opening baseline and punctuation runs are handled separately.
State resets at each
new document. These rules approximate several responses, not all lexical
variation in the original component.
"""
