    elif previous == 'Not' and word in {'the', 'what', 'my', 'your', 'our'}:
        value = -2.5
    elif raw_previous == 'Not' and word == 'a':
        value = -1.6
    elif previous == 'Rate' and word == 'this':
        value = -4.5
    elif previous in {'Like', 'Share', 'Report'} and word == 'this':
        value = -1.9
    elif previous == 'About' and word == 'this':
        value = -1.2
    elif previous == 'Share' and word == 'on':
        value = -0.7
    elif previous == 'Be' and word == 'the':
        value = -1.5
    elif previous == 'Your' and word == 'task':
        value = -2.0
    elif previous == 'Your' and word in {'job', 'role'}:
        value = -0.6
    elif previous == 'Your' and word in {'search', 'password', 'email', 'message'}:
