    elif previous.lower() == 'your' and word == 'browser':
        value = -3.7 if previous == 'Your' else -0.9
    elif previous == 'Your' and word == 'favorite':
        value = 1.5
    elif previous == 'More' and word in {'information', 'ways'}:
        value = -0.7
    elif previous == 'More' and word.lower() == 'from':
        value = -2.0
    elif (previous == 'Published' and word in {'on', 'by'}) or (
        previous == 'Posted' and word == 'on'
    ):
        value = -2.3 if previous == 'Published' else -1.2
    elif word == ':' and (
        previous in {'Views', 'ISBN'} or raw_previous == 'Updated'
    ):
        value = -3.9 if previous == 'Updated' else -1.0
    elif previous == 'Download' and word == 'a':
        value = 1.6
    # Familiar questions, apologies and copular phrases.
    elif before == 'Are' and previous == 'you' and word == 'sure':
        value = -2.9
    elif before.lower() == 'did' and previous == 'you' and word == 'know':
        value = -2.6 if before == 'Did' else -1.3
    elif previous == 'You' and word == 'know':
        value = 0.8
    elif before == 'I' and previous in {"'m", '’m', 'am'} and word == 'sorry':
