    if previous.strip() in METHOD_MODIFIERS and token.strip() == 'function':
        value = 8.8 if previous[:1].isspace() else 6.3
    elif previous.strip() in METHOD_MODIFIERS | {'override'} and token.strip() == 'func':
        value = 2.7
    elif previous.strip() in {'static', 'self', 'parent'} and w == '::':
        value = {'static': 4.1, 'self': 2.6, 'parent': 2.2}[p]
    elif p in {'public', 'protected', 'private'} and w == 'static':
        value = 0.6
    elif p == 'member' and w == 'function':
        value = 6.0
    elif p == 'main':
        if w == 'function':
