        elif w in {'sequence', '-sequence'}:
            value = 5.8
        elif w == 'content':
            value = -5.0
        elif w == 'street':
            value = 2.4
        elif w == 'loop':
            value = 2.0
    elif p == '/main' and w == '/java':
        value = -1.35

    # Ranks, institutions, and other lexicalized modifier-noun compounds.
    elif p in {'major', 'minor', 'big'} and w in {'league', 'leagues', '-league'}:
        value = 3.4 if p == 'major' else 2.2
        if w == '-league' and p == 'major':
            value = 6.5
    elif p in {'major', '-major', 'semimajor'} and w == 'axis':
        value = 4.5
    elif p == 'chief' and w == 'executive':
        value = 4.3
    elif p in {'prime', 'chief'} and w == 'minister':
        value = 1.4 if p == 'prime' else 2.5
    elif p in {'executive', 'central'} and w == 'committee':
        value = 3.6 if p == 'executive' else 2.0
    elif p in {'civil', 'civilized', 'royal', 'physical'} and w == 'society':
        value = -2.7
    elif p == 'primary' and w == 'care':
        value = -3.4
    elif p == 'large' and w == 'language':
        value = -4.5
    elif p == 'big' and w in {'tech', 'tobacco'}:
        value = -4.8
    elif p == 'big' and w == 'ten':
        value = -2.7
    elif previous.strip() == 'General' and token.strip() == 'Public':
        value = 2.5
    elif p == 'public' and w in {'license', 'licence'}:
        value = 4.3
    elif previous.strip() == 'Great' and token.strip() == 'Hall':
        value = 2.7
    elif p == 'most':
        value = {'likely': 0.9, 'certainly': 3.5,
                 'definitely': 4.5}.get(w, value)

    # Chinese/Japanese committee names, including multi-token traditional forms.
    text = recent + token
    if token.endswith(('委员会', '委員會', '常委会', '常委會')):
        standing = recent.endswith(('常务', '常務', '人大', '全国人大'))
        value = 6.8 if standing else 1.0
    elif token in {'会', '會'}:
