        elif recent.endswith('委'):
            value = 4.8
        elif recent.endswith(('基金', '議', '公', '长老')):
            value = 2.2
        elif recent.endswith('機'):
            value = 0.65
    elif recent.endswith('股份') and token == '有限公司':
        value = 5.7
    elif recent.endswith('人民') and token == '代表大会':
        value = 1.6
    elif recent.endswith('首席') and token == '执行':
        value = 4.0
    return (doc, token, text[-20:]), value

"""A fresh-context signal with a few surface-form distinctions.

Large values occur at document starts, including the start of a truncated
row, and any identical-token run immediately following it. Indentation,
message boundaries, punctuation and C-style declarations
have distinct strengths. Ordinary words use coarse grammatical classes,
case and whether the token carries a leading space. Other tokens get zero.
This deliberately leaves the idiosyncratic variation between words out.
"""
import unicodedata

READS = ()

C_DECLARATIONS = {
    'class', 'struct', 'enum', 'const', 'typedef', 'using', 'namespace',
}
DEMONSTRATIVES = {'this', 'that', 'these', 'those'}
CONJUNCTIONS = {'and', 'or', 'but', 'nor', 'yet', 'so'}
QUANTIFIERS = {
    'all', 'some', 'any', 'each', 'every', 'many', 'few', 'most',
    'more', 'much', 'little',
}


def initial_value(token):
    text = token.strip()
    spaced = token.startswith(' ')
    if not text:
        if '\n' in token or '\r' in token:
            return 0.2
        return 4.75 if '\t' in token else 7.3
    if token == '<|im_start|>':
        return 2.72
    if '\n' in token or '\r' in token:
        return 0.6
    if text.isdecimal():
        return -0.58
    if text in {'.', '!'}:
        return 3.4
    if text in {',', '，'}:
        return -1.05
    if text in {'-', '•'}:
        return 2.5 if spaced else 4.7
    if text.startswith(('//', '/*', '#include')):
        return 3.8
    if text == '#':
        return 2.15
    if text == '{':
        return -7.2
    if text.endswith('\\') and text[0] in '{[$':
        return -8.0
    if text.startswith('\\'):
        return -1.8
    if text == "'":
        return 2.5 if spaced else 3.4
    if text == '"':
        return 2.5 if spaced else 0.3
    if unicodedata.category(text[0]) in {'Ps', 'Pi'}:
        return 1.9
    if unicodedata.category(text[0]) in {'Pe', 'Pf'}:
        return 0.5
    if text in C_DECLARATIONS:
        return 6.0 if spaced else 7.0
    word = text.lower()
    if word == 'the':
        return -0.7
    if word in {'a', 'an'}:
        return 1.7
    if word in DEMONSTRATIVES:
        return -0.45
    if word in CONJUNCTIONS:
        return -0.6
    if word == 'of':
        return -1.8
    if word == 'to':
        return 1.7
    if word in {'is', 'are'}:
        return -1.0
    if word in {'have', 'has', 'had'}:
        return 1.45
    if word in {'not', 'no', 'never', 'none', 'neither'}:
        return 2.5
    if word in QUANTIFIERS:
        return 0.1
    if not text.isascii() and text[0].isalpha():
        return 1.6
    if spaced:
        return 0.65
    return 1.8 if text.isupper() else 1.45


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token_id = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        first_id, unchanged = token_id, True
    else:
        first_id = carry[1]
        unchanged = carry[2] and token_id == first_id
    value = initial_value(prefix.token_strings[-1]) if unchanged else 0.0
    return (doc, first_id, unchanged), value

"""Local spelling families around w, not a semantic word category.

Crew/brew/screw and wreck/weld/wound spellings give negative responses;
short h/z/k/g+w fragments give positive ones. Splitting a spelling family
across tokens strengthens its response. Ordinary complete words mostly
receive zero. A carriage-return-only document opening is a separate case.
"""
import re
READS = ()

# Spelling families; inflections are handled below, not listed separately.
ROOTS = {
    'screw': -6.3,
    'crew': -5.22,
    'brew': -5.08,
    'wreck': -4.66,
    'weld': -2.83,
    'wound': -2.56,
    'wrench': -1.98,
    'unwed': -2.0,
    'shrew': -3.82,
}
# The letter immediately before a separately tokenized w fragment.
LEFT = {
    'c': -3.79,
    'e': -1.08,
    'g': 1.2,
    'h': 1.26,
    'j': 0.53,
    'k': 2.6,
    'z': 2.47,
}
OTHER = {
    'sch': 2.33,
    're': -3.13,
    'le': -3.67,
    'cc': -4.68,
    'cluster': 1.41,
    'cw': -2.35,
    'following': 2.3,
    'lew': -2.8,
    'unw': -0.53,
    'winding': -0.86,
}

VALUES = ROOTS | LEFT | OTHER


def feature(before, previous, token):
    """Choose one local spelling rule and its token-boundary scaling."""
    match = re.search(r'[^\W\d_]+\Z', token)
    tail = match.group() if match else ''
    joins = bool(tail and tail == token)
    before = before if joins else ''
    word = (before + tail).lower()
    start = len(before)
    for root in ROOTS:
        if root == 'brew' and word.endswith(('hebrew', 'hebrews')):
            continue
        if root == 'screw' and tail.lower().startswith('crew'):
            continue
        m = re.search(root + r'(s|ed|ing|er|ers|age)?$', word)
        if not m:
            continue
        suffix = m.group(1) or ''
        if m.start() + len(root) <= start:
            # The root was already present; this token adds an inflection.
            if suffix not in ('s', 'ed', 'ing', 'er', 'ers'):
                continue
            factor = .95 if suffix in ('ed', 'ing') else .25
        else:
            factor = {'s': .75, 'ed': .75, 'ing': .65, 'er': .6,
                      'ers': .5, 'age': .25}.get(suffix, 1.0)
            if m.start() < start:
                # The root itself straddles a token boundary.
                factor *= 1.6
        return root, factor

    short = token.lower()
    if joins and before and short.startswith('w') and len(short) <= 4:
        left = before[-1].lower()
        if before.lower().endswith('ck'):
            return '', 0.0
        if left in 'ce' and short not in ('w', 'we', 'ws'):
            return '', 0.0
        key = left if left in LEFT else ''
        if before.lower().endswith(('sch', 'sh')):
            key = 'sch'
        if before.lower().endswith(('re', 'le')):
            key = before[-2:].lower()
        if before.lower().endswith(('cc', 'ec', 'sc')):
            # Stronger C-W spellings, including acronym fragments.
            key = 'cc'
        return key, 1.0 if short == 'w' else .65
    if word.endswith(('schw', 'fchw', 'zw', 'kw', 'cw')):
        return ('cw' if word.endswith('cw') else 'cluster'), 1.0
    if joins and previous.lower().endswith('w'):
        if before.lower().endswith(('schw', 'fchw', 'zw', 'kw')):
            if short.startswith(('an', 'isch', 'ert')):
                return 'following', 1.0
    if short == 'lew':
        return short, 1.0
    if short.strip().endswith('unw'):
        return 'unw', 1.0
    if short.strip() == 'winding':
        return 'winding', 1.0
    return '', 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        word, previous, empty = '', '', True
    else:
        _, word, previous, empty = carry
    token = prefix.token_strings[-1]
    key, scale = feature(word, previous, token)
    value = VALUES.get(key, 0.0) * scale
    if token == '\r' and empty:
        value = 5.5
    empty = empty and not token.strip('\r')
    match = re.search(r'[^\W\d_]+\Z', token)
    if match:
        word = ((word if match.start() == 0 else '') + match.group())[-32:]
    else:
        word = ''
    return (doc, word, token, empty), float(value)

"""Sparse spelling responses, especially school/campus spellings.

校 means school (also proofread/calibrate); 교 is the corresponding
Korean syllable.  These are spelling tests, not an education classifier.
Other peaks include clamp (夹/夾), compare (较/較), post (掲), card (卡),
Japanese kana spellings, and Thai ครู (teacher).
A document-initial // newline also fires.
A short byte tail handles split characters.  Everything else is zero.
"""
READS = ()
LONG_VOWEL_KATAKANA_PREFIX = "ー".encode() + "カ".encode()[:2]


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, first = b'', True
    else:
        tail, first = carry[1], False
    raw = prefix.token_bytes[-1]
    text = raw.decode('utf-8', 'ignore')
    joined = (tail + raw).decode('utf-8', 'ignore')
    # Only inspect newly emitted characters, including a split character.
    old = tail.decode('utf-8', 'ignore')
    fresh = joined[len(old):]
    spelling = fresh.strip()
    value = 0.0
    if '校' in fresh:
        value = 5.9 if spelling == '校' else 3.4
    elif spelling in ('夾', '夹'):
        value = 6.5 if '夾' in fresh else 4.8
    elif spelling == '較':
        value = 2.1
    elif spelling == '较':
        value = 1.3
    elif spelling == '掲':
        value = 3.0
    elif spelling == '卡':
        value = 1.0
    elif spelling in ('교', '학교', '대학교'):
        if spelling == '교':
            value = 3.0 if fresh.startswith(' ') else 2.1
        else:
            value = 1.3 if spelling == '학교' else 2.4
    elif spelling == '카':
        value = 1.1
    elif spelling == '갈':
        value = 3.0
    elif spelling == 'カ':
        value = 0.85
    elif spelling == 'しか':
        value = 1.6
    elif joined.endswith('ครู'):
        value = 3.0
    elif raw == '夾'.encode()[:2]:
        value = 3.0
    elif raw == LONG_VOWEL_KATAKANA_PREFIX:
        value = 3.7 if old.endswith('カ') else 0.5

    lower = joined.lower()
    if lower.endswith(('campus', 'campuses')):
        if text.lower().lstrip(' -') in ('campus', 'campuses'):
            value = 2.6 if 'C' in text else (2.4 if '-' in text else 1.3)
        else:
            value = 3.3 if text.lower() == 'ampus' else 4.5
    if text == '//\n' and (first or tail.endswith(b'<|endoftext|>')):
        value = 4.85
    return (doc, (tail + raw)[-32:]), value

