    if s == ' ' and re.search(r'(?:={2,3}|!=)\s*$', before):
        return 1.19
    if q == '=':
        return 0.26 if s == '=' else 0.06
    # Header cue in documents whose title is explicitly labeled.
    if q == ':' and re.search(r'(?:^|<\|endoftext\|>)Title$', before):
        return 9.09
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    value = activation(s, before)
    return (doc, (before + s)[-180:]), value

"""A surface-form approximation of a participle/gerund signal.

English -ing forms start with negative priors. Determiners and technical
noun modifiers make them more noun-like, hence less negative. Dictionary
word classes and word frequency supply lexical priors. The spelling is joined
across tokens, ignoring known non-inflected roots such as "string". A few
Romance gerund and Cyrillic suffix fragments receive negative constants too.
These are spelling heuristics, not a grammatical parser. State resets at each
document boundary.
"""
import regex as re
from functools import lru_cache
import wordnet
from wordfreq import zipf_frequency

READS = ()
DETERMINERS = set('a an the this that these those my your his her its our their '
                   'some any each every no another'.split())
AUXILIARIES = set('am is are was were be been being keep keeps kept continue '
                  'continues continued start started stop stopped not still'.split())
GERUND_CONTEXT = set('by without before after while when upon despite instead than'.split())
TECHNICAL_MODIFIERS = set('machine deep language data computer image text signal '
                          'pattern speech'.split())
PARTICIPIAL_PREPOSITIONS = {'according', 'including', 'concerning', 'regarding'}
NOUN_PRIORS = {
    'act': 0.08, 'artifact': 0.19, 'cognition': 0.19,
    'communication': 0.06, 'process': 0.25, 'quantity': 0.37,
    'state': -0.18, 'time': -0.23,
}

@lru_cache(maxsize=20000)
def lexical_prior(word):
    forms = wordnet.base_forms(word, 'verb')
    inflected = any(base != word for base in forms)
    known = bool(wordnet.parts_of_speech(word))
    if known and not inflected:  # e.g. thing, string, spring: not -ing forms
        return None
    base_frequency = max([zipf_frequency(b, 'en') for b in forms if b != word]
                         or [zipf_frequency(word, 'en')])
    value = -0.57 - 0.38 * inflected + 0.19 * (not known)
    value += 0.146 * zipf_frequency(word, 'en') - 0.083 * base_frequency
    categories = wordnet.categories(word, 'noun')
    value += sum(weight for name, weight in NOUN_PRIORS.items()
                 if 'noun.' + name in categories)
    return value


@lru_cache(maxsize=10000)
def other_ending(word, token):
    """Recognise suffix-shaped continuations, not entire-word identities."""
    if len(word) <= len(token.strip()):
        return 0.0
    if re.fullmatch(r'\p{Script=Cyrillic}+', word):
        if token in ('ая', 'яя'):
            return -1.6
        if token in ('ав', 'ив'):
            return -1.1
        if token == 'я':
            return -1.0
        if token == 'сь' and word.endswith(('аясь', 'яясь')):
            return -1.0
    lower = word.lower()
    if wordnet.parts_of_speech(lower):
        return 0.0
    if lower.endswith(('ando', 'endo')):
        return -0.75 if word[0].isupper() else -1.6
    if lower.endswith('ant'):
        return -1.05
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else b''
    token = prefix.token_strings[-1]
    tail = (tail + prefix.token_bytes[-1])[-512:]
    carry = (doc, tail)
    if not token.lower().endswith(
            ('ing', 'ant', 'ando', 'endo', 'ая', 'яя', 'ав', 'ив', 'я', 'сь')):
        return carry, 0.0
    tail = tail.decode('utf-8', 'ignore')
    if not token.lower().endswith('ing'):
        match = re.search(r'(\p{L}+)$', tail)
        value = other_ending(match[1], token) if match else 0.0
        return carry, value
    match = re.search(r'([A-Za-z]+)$', tail)
    if not match:
        return carry, 0.0
    word = match[1]
    before = tail[:match.start()]
    previous = re.search(r'([A-Za-z]+)[^A-Za-z]*$', before)
    previous = previous[1].lower() if previous else ''
    value = lexical_prior(word.lower())
    if value is None:
        return carry, 0.0
    if previous in DETERMINERS:
        value += 0.73
    if previous in AUXILIARIES:
        value -= 0.23
    if previous in GERUND_CONTEXT:
        value -= 0.47
    if previous in ('of', 'for'):
        value -= 0.15
    if previous in ('to', 'and', 'or'):
        value -= 0.21
    if previous in TECHNICAL_MODIFIERS:
        value += 0.31
    if re.search(r'[,;:]\s*$', before):
        value -= 0.25
    if any(c.isupper() for c in word[1:]):
        value += 0.48
    if before.endswith(('.', '_')):
        value += 0.15
    if len(word) > len(token.strip()):
        value -= 0.26
    if word.lower() in PARTICIPIAL_PREPOSITIONS:
        value *= 0.4
    return carry, float(value)

programs.haiku:
"""Layer-1 MLP down_proj component 4562: present participles and gerunds.

What it does: it is negative on an English "-ing" verb form (or Spanish/Portuguese
"-ando/-endo" gerund) used as a verb, e.g. "he said, whistling", "when cleaning",
"is going". It is most negative right after when/while/before/after/not/then, a bit less
after a comma or conjunction, and about -0.8 otherwise. When the -ing word follows a
determiner ("the recording", "a loading") it is a noun or adjective and is mildly positive.
Prepositions and fixed words that only look like -ing forms ("according", "during",
"following", "something", "nothing", "morning") stay at 0. Every other token predicts 0.

Word pieces are joined into whole words, so "whist|ling" counts as one word.
"""
READS = ()

DETERMINERS = {"the", "a", "an", "this", "that", "their", "your", "our", "its", "my", "his",
               "her", "new", "current", "most", "every", "each", "some", "any"}
CLAUSE_STARTS = {"when", "while", "before", "after", "not", "then", "also", "so", "now", "never"}
JOINERS = {",", "and", "or", "but", "."}
PREPOSITIONS = {"according", "during", "following", "concerning", "including", "regarding"}
NOUNS_AND_ADJECTIVES = {"something", "everything", "nothing", "anything", "thing", "spring",
                        "morning", "evening", "clothing", "wedding", "ceiling", "string", "bring",
                        "meaning", "interesting", "understanding", "finding", "feeling"}


def word_start(strings, end):
    """Index of the first piece of the word whose last piece is strings[end]."""
    j = end
    while j > 0 and strings[j][:1].isalpha():
        j -= 1
    return j


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    j = word_start(strings, len(strings) - 1)
    word = "".join(strings[j:]).strip().lower()
    if not (word.isascii() and word.isalpha()) or len(word) < 5:
        return carry, 0.0
    if not (word.endswith("ing") or word.endswith("ando") or word.endswith("endo")):
        return carry, 0.0
    if word in PREPOSITIONS or word in NOUNS_AND_ADJECTIVES:
        return carry, 0.0
    prev = "".join(strings[word_start(strings, j - 1):j]).strip().lower() if j > 0 else ""
    if prev in DETERMINERS:
        return carry, 0.3
    if prev in CLAUSE_STARTS:
        return carry, -1.4
    if prev in JOINERS:
        return carry, -1.1
    return carry, -0.8

