import calendar
import re
from opencc import OpenCC

READS = ()
_SIMPLIFY = OpenCC('t2s')
_MONTHS = '|'.join(calendar.month_name[1:] + calendar.month_abbr[1:])
_DATE = re.compile(r'(?i)\b(?:' + _MONTHS + r')\.?\s+3$')
_SHORT_STEMS = re.compile(r'(?i)k[uü]rz|kort')
# These are distinct lexical responses, not a claim of one common meaning.
_CHINESE = {
    '内部': -2.5,       # internal / inside
    '外部': -1.5,       # external / outside
    '官方': -3.0,       # official
    '民间': -2.1,       # folk / non-governmental
    '客户端': -2.3,     # client application
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    combined = tail + token
    value = 0.0

    if token in ('0', '1'):
        zero = token == '0'
        if tail.endswith('3'):
            embedded = len(tail) > 1 and tail[-2].isdigit()
            value = (0.63 if zero else 0.32) if embedded else (
                1.23 if zero else 0.85)
            if not embedded:
                if _DATE.search(tail):
                    value = 2.45 if zero else 1.9
                elif tail.endswith(':3'):
                    value = 1.55 if zero else 0.80
                elif tail.endswith(('.3', ',3')):
                    value = 0.90 if zero else 0.50
        elif tail.endswith('3.'):
            value = 0.53 if zero else 0.45
        elif zero and tail.endswith('3,'):
            value = 0.38
    elif not tail and token == '<|endoftext|>':
        value = 2.05
    elif word == 'of' and re.search(r'(?i)\bend\s*$', tail):
        value = 0.38
    elif word == 'of' and re.search(r'(?i)\bheart\s*$', tail):
        value = 0.30
    elif word == 'before':
        if re.search(r'(?i)\bjust\s*$', tail):
            value = 1.0
        elif re.search(r'(?i)\bright\s*$', tail):
            value = 0.68
        elif re.search(r'(?i)\bshortly\s*$', tail):
            value = 0.52
    elif word == 'thirty':
        value = 0.61
    elif word == 'short':
        value = 0.26
    elif word == 'shortly':
        value = 1.35
    else:
        # A stem must have just been completed, not merely be in the past.
        for match in _SHORT_STEMS.finditer(combined[-30:]):
            if match.end() > len(combined[-30:]) - len(token):
                value = 1.0 if 'ü' in match.group().lower() else 2.0
        if (combined.lower().endswith(('short', 'shorth', 'shorty', 'shortly'))
                and word in ('ort', 'orth', 'y', 'ly')):
            value = 1.8
        if any(ch in token for ch in ('部', '方', '间', '間', '端')):
            value = _CHINESE.get(_SIMPLIFY.convert(token.strip()), value)

    return (doc, combined[-100:]), value

"""Sparse Unicode surface rules, not a general semantic detector.

Predict negative values for nonbreaking spaces beside operators, code marks
or capital labels; damaged-encoding fragments; certain standalone Han forms
(black, gray/ash, state); and specific split Han/kana characters. Two mojibake
patterns and a split glowing-star emoji get positive values. Otherwise zero.
Only the previous token and 96 recent bytes are kept, reset per document.
The rules deliberately leave most word-specific variation unexplained.
"""
import unicodedata as ud
import regex

