def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = b'', b''
    else:
        _, previous, tail = carry
    b = prefix.token_bytes[-1]
    s = b.decode('utf-8', 'replace')
    prev = previous.decode('utf-8', 'replace').strip()
    recent = (tail + b).decode('utf-8', 'ignore')
    value = 0.0

    if s == '\u00a0':
        if prev in {'×', '&', '&&'}:
            value = -1.8
        elif prev in {'–', '—', '−', '⋅'}:
            value = -0.9
        elif '`' in prev:
            value = -0.5
        elif prev and all(c in '<>|{}' for c in prev):
            value = -0.8
        elif prev and all(c in '?!' for c in prev):
            value = -0.7
        elif prev.isupper() and prev.isalpha():
            value = -0.5
        elif prev and all(c == ')' for c in prev):
            value = -0.25

    # C2 introduces Latin-1 characters. A separate C2 after non-ASCII text
    # often belongs to text damaged by decoding UTF-8 in the wrong encoding.
    elif b == b'\xc2':
        if prev and ord(prev[-1]) > 127:
            value = -0.8 if ud.category(prev[-1]) == 'Cc' else -1.7
    elif b == b'\xc2\x80\xc2' and prev.endswith('â'):
        value = 0.7
    elif s == '™' and prev.endswith('Ђ'):
        value = 1.8

    elif s == '黑':                 # Standalone black, not merged compounds.
        value = -0.75
    elif s == '灰':                 # Gray / ash.
        value = -3.4
    elif s == '灰色':
        value = -1.8
    elif s == '态':                 # Standalone state/condition character.
        value = -2.7
    elif s == '態':
        japanese = regex.search(r'[\p{Hiragana}\p{Katakana}]', recent)
        value = 0.0 if japanese else -1.1

    # UTF-8 E7 81 starts the small Han range containing fire and ash.
    # Predict here even before its final byte arrives.
    elif b == b'\x81' and previous.endswith(b'\xe7'):
        value = -3.5
    # Finish katakana chi after a long-vowel mark, or hiragana chi after shi.
    elif b == b'\x81' and previous.endswith('ー'.encode() + b'\xe3\x83'):
        value = -1.1
    elif b == b'\xa1' and previous.endswith('し'.encode() + b'\xe3\x81'):
        value = -3.0
    elif b == b'\x9f' and recent.endswith('🌟'):
        value = 2.1
    elif s == '⇧':
        value = -0.7

    return (doc, b, (tail + b)[-96:]), float(value)

