AFTER_INITIAL_EIGHT = (
    2.50, 0.53, 2.77, 0.64, -1.04,
    0.43, 3.43, 0.33, 0.65, -0.04,
)
AFTER_INTERNAL_EIGHT = (
    0.70, 0.0, 0.90, 0.08, -1.60,
    0.02, 1.0, 0.04, 0.01, -0.02,
)
