'''.split())
GERMAN = set('''
    ich du er sie es wir ihr der die das den dem ein eine und nicht mit von zu ist
'''.split())
ROMANCE = set('''
    il lo gli che non di del della sono io mi ti ci vi
    el los las que se no por para con una yo
'''.split())
NORDIC = set('''
