GERMAN_HAVE = set('''
    habe hast haben habt hatte hatten hattet hätte hätten
'''.split())
ROMANCE_HAVE = set('''
    ha hai ho hanno abbiamo avete hemos habéis han había habían
'''.split())
ITALIAN_PAST = set('''
    aveva avevo avevamo avevate avevano avrebbe avrebbero avessi avesse
