        if len(word) == 3:
            if word == 'mus' and not spaced:
                return 5.5
            if word == 'mut' and not spaced:
                return 2.7
            return 3.9 if word[-1] in 'stdx' else 2.2
        return 0.7 if len(word) == 4 else 0.0
    if len(word) <= 4 and word.endswith('mus'):
        return 5.7
    if len(word) <= 4 and word.endswith('mu') and 'mm' not in word:
        return 4.5
    return 0.0


