    if len(word) == 1:
        return 6.2
    if word.startswith(('useum', 'uses')):
        return 4.0
    if len(word) > 3:
        return 0.4
    if word in ('ute', 'ung', 'ult', 'uel'):
        return 0.6
    if word.startswith(('un', 'um', 'ul')):
        return 1.5
    if word.startswith(('ur', 'ua', 'ui')):
