        if not (text[0].isupper() and previous[-1].islower()):
            value = u_continuation(anyascii(low))
            if low == 'у':
                value = 2.6
            elif low == 'ю':
                value = 5.5
            elif low.startswith('ую') or low == 'уж':
                value = 1.2
            elif text == 'U' and previous.strip().isupper():
                value = 8.0
