        elif normalize(previous).endswith('mu'):
            if len(text) == 1 or (len(text) <= 2 and text.startswith(('s', 'z'))):
                value = max(value, 0.6 * last)
        elif normalize(previous).endswith('u') and len(text) == 1 and text not in 'aeiou':
            value = max(value, 0.65 * last)

