        value = -1.6
        if NEGATED.search(recent.lower()):
            value = -7.5
        elif re.search(r'\b(?:in|to|my|your|his|her|their|our)\s*$', recent.lower()):
            value = -0.4
        if re.search(r'\b(?:would|do|will) you\s*$', recent.lower()):
