def initial_value(text):
    if text.startswith('<|'):
        return 0.2
    if text in {' ', '\xa0'}:
        return -4.2 if text == '\xa0' else -4.0
    if text == '\t':
        return -3.65
    if text.isspace():
        if '\n' in text:
            return -2.1 if text.count('\n') == 1 else -1.4
        return -2.0
    if text.isdigit():
        return -1.1
    if text == ',':
        return -6.2
    if text == ';':
        return -3.55
    if text == '，':
        return -2.65
    if text.strip() in {'.', ')'}:
        return -1.9
    if text.startswith('$'):
        return -2.9
    if text == 'package':
        return -5.3
    if text and not text.strip('^'):
        return -2.1 * len(text)
    if text.startswith(' '):
        return -0.15
    return -0.4


def step(carry, prefix, upstream):
    text = prefix.token_bytes[-1].decode('utf-8', errors='replace')
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        value = initial_value(text)
        return (doc, text, 0, True), value

    _, previous, position, repeating = carry
    position += 1
    same_start = repeating and text == previous
    value = 0.0
    if same_start:
        value = initial_value(text)
    elif text == ' ':
        if len(previous) >= 2 and not previous.strip(' \t'):
            if '\t' in previous:
                base = -1.4
            elif len(previous) > 4:
                base = -1.1
            else:
                base = -1.4 if len(previous) == 2 else -1.45
            value = base - 0.35 * math.exp(-position / 100)
        elif previous == ' ':
            value = -0.45
        elif previous.endswith('\n'):
            value = -0.05
        else:
            value = 0.05
    elif text == '\t' and previous and not previous.strip(' \t'):
        value = -0.3 if len(previous) == 1 else -0.6
    elif text == '\xa0' and len(previous) > 1 and not previous.strip('\xa0'):
        value = -0.95 if len(previous) % 2 else 0.0
    elif text == '``' and previous.isspace() and '\xa0' in previous:
        value = -0.85
    elif text == '.com':
        back = min(position, 3)
        recent = b''.join(prefix.token_bytes[-back - 1:-1]).lower()
        if recent.endswith(b'github') and not recent.endswith(b'.github'):
            value = -2.0
    return (doc, text, position, same_start), value

