    body = tok.strip(" \t\xa0\r\n")
    if body == "" or all(ch in CLOSERS for ch in body):
        return -2.8
    if re.fullmatch(r"\d+", body):
        return -1.0
    if re.search(r"[A-Za-z]", tok):
        return -0.4
    return 0.0


