    tok = prefix.token_strings[-1]
    if len(prefix.token_strings) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, first_token_value(tok)
    prev = prefix.token_strings[-2]
    if tok == " ":
        if prev == " ":
            return None, -0.46
        if prev != "" and prev.strip(" \t\xa0") == "":
            return None, -1.45
    if tok == "··":
        return None, -0.66
    return None, 0.0

