"""A spelling-fragment detector for Van/van, especially names and syllables.

It recognizes the short fragment, not every word containing those letters.
It also recognizes an... immediately after v. Dutch 'van' and German 'von'
are weaker as ordinary function words than in names. A short text tail is
used to distinguish those contexts; document boundaries clear it. Weaker
responses cover von/wan, short van-extensions, and advance/advances.
Van der continues the name response. A Title: immediately after an
end-of-text marker is a separate, smaller response. Other vowel
continuations after v can be weakly negative; unrecognized tokens are zero.
"""
import re
from anyascii import anyascii
from functools import lru_cache

READS = ()
DUTCH = set('de het een en voor met niet zijn aan ook wordt door bij je uw'.split())
GERMAN = set('der die das ein eine und den dem des nicht sich auf für'.split())
ENGLISH = set('the of and to a in with is was for that this'.split())


@lru_cache(maxsize=160000)
def spelling(text):
    return anyascii(text).lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, previous_raw, tail = '', '', ''
    else:
        _, previous, previous_raw, tail = carry
    raw = prefix.token_strings[-1]
    text = spelling(raw)
    word = text.strip()
    value = 0.0
    latin = raw.isascii()
    if word == 'van':
        if not latin:
            value = 1.9
        elif raw.strip()[0].isupper():
            value = 10.0
        else:
            value = 7.8 if raw[:1].isspace() else 6.0
            words = re.findall(r'[a-z]+', tail.lower())
            nl = sum(w in DUTCH for w in words)
            en = sum(w in ENGLISH for w in words)
            if nl >= 2 and nl > en:
                value = 1.8
    elif word == 'von':
        words = re.findall(r'[a-z]+', tail.lower())
        de = sum(w in GERMAN for w in words)
        en = sum(w in ENGLISH for w in words)
        value = 0.3 if de >= 2 and de > en else 1.5
    elif latin and re.fullmatch(r'[aeiou]vans?', word):
        value = 2.7 if raw[:1].isspace() or word.endswith('s') else 5.5
    elif latin and re.fullmatch(r'[ai]?van[a-z]', word):
        value = 0.7 if word.endswith('t') else 3.6
    elif word in ('advance', 'advances'):
        value = 2.8 if word.endswith('s') else 1.2
    elif word == 'vanilla':
        value = 3.5
    elif word == 'wan' and latin:
        value = 1.3
    elif raw in ('万', '萬'):
        value = 1.6
    elif not raw[:1].isspace():
        if previous.endswith('v'):
            if text.startswith('an'):
                value = 7.0 if len(text) <= 3 else 4.0
                if text.startswith('ant'):
                    value = 2.0
                elif text.startswith(('ann', 'ang')):
                    value = 3.8
                elif len(text) == 3 and text[-1] in 'aiou':
                    value = 5.5 if previous == 'v' else 2.0
            elif text.startswith('on'):
                value = 3.0
            elif text == 'n':
                value = 1.0
            elif text.startswith(('all', 'alt', 'ill', 'ou', 'old', 'iss')):
                value = -1.2
        elif 'v' in previous and text.startswith('an'):
            value = 0.3
        elif previous.endswith('w') and text.startswith('an'):
            value = 1.2
    # Long non-Latin words ending in v are not the strong isolated v cue.
    if previous.endswith('v') and not previous_raw.isascii():
        if previous != 'v':
            value *= 0.2
    if text.startswith('an') and not latin and not raw.startswith('ан'):
        value *= 0.3
    if word == 'der' and previous == 'van':
        value = 8.0
    if raw == ':' and tail.endswith('<|endoftext|>Title'):
        value = 3.0
    last = re.search(r'[^\W\d_]+$', text)
    previous = last.group() if last else ''
    return (doc, previous, raw, (tail + raw)[-180:]), value

"""A document-start pulse, with amplitude set by the first token's form.

Later tokens receive a near-zero background. At a fresh document (including
an initially truncated row), bare words produce a larger pulse than words
with leading space. Case, length, word frequency, script and punctuation
class give a coarse estimate of the remaining token-dependent variation.
"""
import math
import regex
from wordfreq import zipf_frequency

READS = ()


def initial_value(s):
    w = s.strip()
    if s == '<|endoftext|>':
        return 11.3
    if s.startswith('<|'):
        return 3.55
    if len(s) == 2 and s[0] == '\\' and s[1] in "abfnrtv0'\"\\":
        return 9.7
    if not w:
        if not s.isascii():
            return 5.8
        if '\n' in s or '\r' in s:
            return 3.6
        return 1.43 if s == '\t' else 0.1
    if w.isascii() and w.isdigit():
        return 2.83
    if w.isascii() and w.isalpha():
        case = 2 if w.isupper() else 1 if w.istitle() else 0
        bases = (2.25, 2.43, 0.82) if s[0].isspace() else (4.18, 5.32, 4.26)
        value = bases[case] + 0.28 * zipf_frequency(w.lower(), 'en')
    elif regex.search(r'\p{Script=Han}', w):
        value = 3.91
    elif regex.search(r'\p{Script=Cyrillic}', w):
        value = 3.6 if s[0].isspace() else 6.8 if w[0].isupper() else 4.8
    elif any(c.isalpha() and ord(c) > 127 for c in w):
        value = 4.59
    elif '\ufffd' in w:
        value = 3.15
    elif w.startswith('#') and w[1:].isalpha():
        value = 2.04
    elif all(not c.isalnum() for c in w):
        if w[0] in '\'"`':
            if s[0].isspace():
                value = 3.6
            elif all(c == w[0] for c in w):
                value = 7.3 if w[0] == '"' else 5.6
            else:
                value = 4.4
        elif w[0] in '([{':
            value = 3.4 if s[0].isspace() else 5.2
        elif w[0] in '.,;:)]}':
            value = 2.95
        elif w[0] in '#*':
            value = 6.08
        else:
            value = 3.86
    else:
        value = 4.70
    return max(-0.5, value - 0.81 * math.log(max(1, len(w))))


def step(carry, prefix, upstream):
    first = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    value = initial_value(prefix.token_strings[-1]) if first else -0.0032
    return None, float(value)

"""Negative responses to separators inside compound names and expressions.

Hyphens following alphabetic text and Romance elision apostrophes are the
strongest cases. Slashes, abbreviation/version dots, and the blank following
a numbered label have weaker responses. Persian zero-width word joiners
also receive a negative response. Ordinary punctuation stays near zero.
Only the current token and a short, document-local text suffix are needed.
"""
import re
import unicodedata

READS = ()

ELISION = set('d l j m n t s c qu un all dall dell nell sull quest'.split())
COMPOUND_PREFIX = set('''
anti auto co cross ex extra inter mid multi non post pre pro re
semi sub super trans ultra under
'''.split())
NUMBERED_LABEL = set('''
example case question problem exercise figure fig table section chapter
part volume page line step study phase group level class type grade
zone district ward model version exam lesson test trial requirement
algorithm theorem lemma proposition equation formula rule option item task check
'''.split())
SOFTWARE = set('''
python javascript java windows android ios ubuntu gpt html css sql
'''.split())
TITLES = {'mr': -2.1, 'mrs': -1.8, 'ms': -1.2, 'dr': -1.5,
          'prof': -1.0, 'jr': -0.8, 'sr': -0.8, 'st': -0.7}


def predict(token, text):
    last = text[-1:]
    match = re.search(r'[^\W\d_]+$', text)
    word = match[0] if match else ''
    lower = word.lower()
    if token in ('-', '‐') and last.isalpha():
        script = unicodedata.name(last, '')
        if 'CYRILLIC' in script:
            return -4.4
        if 'LATIN' in script or 'GREEK' in script:
            if re.search(r'\d[^\W\d_]+$', text):
                return -1.2
            if lower in COMPOUND_PREFIX:
                return -4.0
            if len(word) == 1:
                return -1.4 if word.isupper() else 0.0
            return -3.0
    if token in ("'", '’'):
        if word in ELISION and not text.endswith("'" + word):
            return -5.6 if word not in {'c', 'm', 'n', 's', 't'} else -2.0
    if token == '/' and last.isalpha():
        if 'LATIN' in unicodedata.name(last, ''):
            return -1.1
    if token == '::' and last.isalpha():
        return -2.3 if word[:1].isupper() else -0.8
    if token == '.':
        if re.search(r'\d+\.\d+$', text):
            return -1.9
        dotted = re.search(r'[^\W\d_]\.[^\W\d_]+$', text)
        if dotted and not text.endswith(('i.e', 'e.g')):
            return -1.5
        if lower in TITLES:
            return TITLES[lower]
        if lower in {'fig', 'al', 'app'}:
            return -0.5
    if token == ' ':
        if lower in {'algorithm', 'test', 'type', 'grade', 'district'}:
            return -2.0
        if lower in NUMBERED_LABEL:
            return -0.85
        if lower in SOFTWARE:
            return -2.0
        if lower in {'early', 'late'}:
            return -0.8
    if token == '\u200c' and last:
        if 'ARABIC' in unicodedata.name(last, ''):
            return -5.8  # Persian's zero-width, within-word separator.
    if token in ('·', '・') and last.isalpha():
        return -1.9
    return 0.0


def step(carry, prefix, upstream):
    document = int(prefix.document_ids[-1])
    if carry is None or carry[0] != document:
        text = ''
    else:
        _, text = carry
    token = prefix.token_strings[-1]
    value = predict(token, text)
    return (document, (text + token)[-160:]), value

programs.haiku:
"""Draft 6: punctuation that binds a piece of text to the word before it, with no space.

The component goes negative on these marks, and on little else:
  - a hyphen inside a word (first-aid, extra-ordinary, COVID-19): strong after a word, weak after one letter,
  - a slash inside a word or path (HTTP/1.1, rails/activerecord),
  - a double colon after a name (Math::Prime, DB::table),
  - an apostrophe after a French elided word (l'homme, d'ions, dell'anno),
  - a period that ends an abbreviation (U.S., I.T., Mr., Dr., St., et al.),
  - a period inside a dotted version chain (1.0.2),
  - a space after a capitalised word, where a number or label often follows (Python 3, Route 91).
Everything else is about zero.
"""
READS = ()

ELIDED = {"l", "d", "n", "m", "s", "j", "c", "qu", "all", "dell", "quell", "un"}
ABBREVIATIONS = {"Mr", "Mrs", "Ms", "Dr", "St", "Jr", "Sr", "Prof", "vs", "Inc", "al", "Eq", "FIG", "Fig"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    prev = prefix.token_strings[-2]
    word = prev.strip()
    glued = prev[-1:].isalpha()  # the mark follows a letter with no space between
    if tok == "-" and glued:
        return None, -3.1 if len(word) >= 2 else -1.0
    if tok == "/" and glued:
        return None, -1.2
    if tok == "::" and glued:
        return None, -2.4 if word[:1].isupper() else -0.8
    if tok in ("'", "’") and prev.startswith(" ") and word in ELIDED:
        return None, -6.0
    if tok == "." and (word in ABBREVIATIONS or (prev.startswith(".") and prev[-1:].isupper())):
        return None, -1.4
    if tok == "." and prev[-1:].isdigit() and len(prefix.token_strings) > 2 and prefix.token_strings[-3] == ".":
        return None, -2.1
    if tok == " " and prev.startswith(" ") and prev[1:2].isupper():
        return None, -0.5
    return None, 0.0

programs.sol:
"""Approximate a document-onset signal, not a topic detector.

Emit zero after the first token of each document segment (including a row's
start). At the onset, estimate the amplitude from familiar token classes:
code/escape syntax is strongest, articles and possessives are next, ordinary
words and non-Latin text are weaker. WordNet distinguishes dictionary words
from fragments; long dictionary words receive less signal. The estimates
are class averages, not a memorized token vocabulary.
"""
from functools import lru_cache
import unicodedata
import wordnet

READS = ()
ARTICLES = set('a an the'.split())
PREPOSITIONS = set('of to in for on at by from with into over under through '
                   'between against about before after without within upon'.split())
CONJUNCTIONS = set('and or but if as than because while although unless nor so '
                   'that'.split())
PRONOUNS = set('i you he she it we they me him her us them this these those '
               'what who which where when how there'.split())
POSSESSIVES = set('my your his its our their mine yours hers ours theirs'.split())
AUXILIARIES = set('is are was were be been being am do does did have has had '
                  'can could will would shall should may might must'.split())
CODE_WORDS = set('class def const var let function import return public private '
                 'static void int long float double char string package namespace '
                 'interface enum struct typedef extends implements async await '
                 'export require'.split())


@lru_cache(maxsize=8192)
def onset(s):
    w = s.strip()
    low = w.lower()
    if s == '<|endoftext|>':
        return 15.8
    if s.startswith('<|') or (w.startswith('<') and w.endswith('>')):
        return -1.5
    if w == r'\t':
        return 37.1
    if w.startswith(('\\"', "\\'")):
        return 24.5
    if w == r'\n':
        return 17.0
    if '\t' in s:
        return (18.3 if s == '\t' else 6.0) if not w else 17.0
    if any(unicodedata.category(c) == 'Cc' and c not in '\r\n' for c in s):
        return 18.0
    if not w:
        if '\n' in s:
            return 9.5 if '\r' in s else 3.5
        return 0.1 if s.isascii() else 6.0
    if w.isascii() and w.isdigit():
        return 4.3
    letters = ''.join(c for c in w if c.isalpha())
    if letters and not all('LATIN' in unicodedata.name(c, '') for c in letters):
        return 0.7
    if w.startswith('#'):
        return 7.2 if letters else 10.3
    if w.startswith('\\'):
        return 9.7
    if w.startswith(('/*', '//')):
        return 12.3
    if low in ("'s", '’s', "'t", "n't", "'re", "'ve", "'ll", "'d"):
        return 8.0
    if w.startswith(('.', '_', '/', '"')) and letters:
        return 14.2
    if not letters:
        if w[0] in '\"\'`':
            return 21.5 if w.startswith(('"""', "'''")) else 9.0
        if w in ('.', ',', ';', ':', ')', ']', '}'):
            if '\n' in s:
                return 3.0 if s.count('\n') > 1 else 6.5
            if not s.startswith(' '):
                return 0.2 if w in ('.', ',', ')') else 3.0
        if w in ('(', '[', '{'):
            return 4.5 if w == '(' else 8.0
        return 3.5 if len(w) == 1 else 8.0
    if not w.isalpha():
        return 11.0
    if low in ARTICLES:
        return 6.2
    if low in POSSESSIVES:
        return 6.9
    if low in PREPOSITIONS:
        return 3.8 if s.startswith(' ') else 5.8
    if low in CONJUNCTIONS:
        return 1.8
    if low in PRONOUNS:
        return 2.3
    if low in AUXILIARIES:
        return 3.3
    if low in {'not', 'no', 'never'}:
        return 3.8
    if low in CODE_WORDS and not s.startswith(' '):
        return 7.0
    if len(w) == 1:
        return 3.8
    if not wordnet.parts_of_speech(low):
        return 3.0
    # Longer complete words carry less onset signal than short pieces.
    length = min(len(w), 10)
    boundary = 0.8 if s.startswith(' ') and length >= 4 else 0.0
    return 3.9 - 0.32 * length - boundary


def step(carry, prefix, upstream):
    if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
        return None, 0.0
    return None, onset(prefix.token_strings[-1])

"""Approximate a response to long numbers and opaque character strings.

Activation jumps at the fourth consecutive ASCII digit and then rises,
except for common four-digit calendar years. Hashes, mixed identifiers,
and DNA/protein-alphabet strings respond when split into short chunks.
Short numbers stay near zero. A separate rule reproduces the negative
colon response in a document-initial 'Title:' label.

Only bounded word/digit suffixes and short-chunk counts are carried;
everything resets when the document changes. Lexical offsets are omitted.
"""
import re

READS = ()
DNA_BASES = frozenset("ACGT")
AMINO_ACIDS = frozenset("ACDEFGHIKLMNPQRSTVWY")


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        digits, word, pos, before, pieces = '', '', 0, '', 0
    else:
        _, digits, word, pos, before, pieces = carry
    s = prefix.token_strings[-1]
    old_word = word
    if s.isascii() and s.isdigit():
        digits = (digits + s)[-40:]
    else:
        digits = ''
        before = s[-1:]
    m = re.search(r'[A-Za-z0-9]+\Z', word + s)
    word = m.group()[-80:] if m else ''
    if s.isascii() and s.isalnum():
        pieces = pieces + 1 if len(s) <= 3 else 0
    else:
        pieces = 1 if word and len(word) <= 3 else 0
    n = len(digits)
    value = 0.0
    if n:
        if n < 4:
            value = (0.0, 0.02, 0.08, 0.04)[n]
            if before == '.' and n == 2:
                value = 0.21
            if n == 3 and digits == '000':
                value = -0.15
        elif n == 4:
            century = digits[:2]
            if century in ('19', '20'):
                value = 0.06
            elif century == '18':
                value = 0.48
            else:
                value = 1.03
        else:
            value = min(1.7, 1.25 + 0.12 * (n - 5))
    # Opaque identifiers alternate letters/digits or use hexadecimal.
    transitions = sum(a.isdigit() != b.isdigit()
                      for a, b in zip(word, word[1:]))
    if pieces >= 4 and len(word) >= 5 and transitions >= 3:
        if sum(c.isdigit() for c in word) >= 3 and s.isascii() and s.isalnum():
            value = max(value, 1.15 if s.isalpha() else 1.45)
    # Biological sequence alphabets, not a list of observed strings.
    dna = len(word) >= 8 and set(word) <= DNA_BASES
    protein = len(word) >= 12 and set(word) <= AMINO_ACIDS
    if pieces >= 4 and (dna or protein) and s.isalpha():
        value = max(value, min(1.5, 0.9 + 0.15 * (pieces - 4)))
    if pieces >= 4 and len(word) >= 7 and re.fullmatch(r'[0-9A-Fa-f]+', word):
        if any(c.isdigit() for c in word) and any(c.isalpha() for c in word):
            value = max(value, 1.3 if s.isalpha() else 1.65)
    if pos == 1 and old_word == 'Title' and s == ':':
        value = -6.7
    return (doc, digits, word, pos + 1, before, pieces), value

"""A mostly negative response to physics vocabulary and split phys-/fiz- roots.

'Physical', 'quantity', and 'units' are weaker and context dependent: recent
scientific language distinguishes them from bodily or commercial uses. There
is also a positive response to bare code declarations at a document's start,
and a negative one to an opening spaced period. Some letter continuations
respond outside physics too. State keeps 160 preceding characters and the
previous token; it resets at document boundaries.
"""
import re
import unicodedata
from anyascii import anyascii
from functools import lru_cache

READS = ()
SCIENCE = re.compile(
    r'quantum|particle|mass|energy|force|mechanic|dimension|parameter|'
    r'diffusion|molecular|thermo|neutron|proton|electron|dielectric|'
    r'physics|hamilton|eigen|scalar|vector|numeric|measur|calculus|'
    r'equation|symmetr|mathemat|observabl|spatial|decay|qubit|integral|'
    r'precise|magnitude|central|scale|contour|variation|sine|angle|'
    r'gravity|accel|velocity|electric|momentum|density'
)
MATH = re.compile(r'\\(?:frac|theta|sum|int|sigma)|[=^]')
BULK = {'large', 'small', 'smaller', 'sufficient', 'total', 'vast',
        'high', 'immense', 'low'}

@lru_cache(maxsize=8192)
def latin(s):
    return anyascii(unicodedata.normalize('NFKC', s)).lower()


def activation(token, previous, context, start):
    s, prev = latin(token), latin(previous)
    w = s.strip()
    if start and token == 'package':
        return 5.19
    if start and token in ('using', 'function', 'const', 'var', 'module', 'from'):
        return 1.7
    if start and token == ' .':
        return -2.43
    if token.strip() == '物理':
        return -6.3
    if 'physics' in s or 'ysics' in s:
        # CamelCase names in code have a weaker response than prose.
        if (token[:1].isupper() and previous[-1:].isascii()
                and previous[-1:].isalpha()):
            return -3.5
        return -7.2 if token.strip()[:1].isupper() else -6.3
    if 'physicist' in s:
        return -3.5
    if 'ysical' in s and not w.startswith('physical'):
        if previous.startswith('.'):
            return 0.0
        tail = latin(context[-30:]) + s
        return -8.5 if 'astroph' in tail else -3.9
    if w in ('physical', 'physically', 'quantity', 'quantities', 'units'):
        ctx = latin(context)
        science = bool(SCIENCE.search(ctx) or MATH.search(ctx))
        if w in ('physical', 'physically'):
            if science:
                return -2.6
            return -0.1
        if w in ('quantity', 'quantities'):
            if prev.strip() in BULK or re.search(
                r'profit|demand|price|contract|inventory|purchas', ctx
            ):
                return 0.15
            if prev.strip() == 'physical':
                return -4.8
            return -2.6 if science else -0.2
        if prev.strip().isdigit():
            return 0.0
        if prev.strip() in ('in', 'no', 'different') or re.search(
            r'\bsi\b|metric|standard|convert|basic|measure', ctx
        ):
            return -1.0
        return 0.0
    if 'physician' in w:
        return 0.0
    if 'ophys' in s:
        return -3.5
    if 'phys' in s or w in ('fys', 'fiz', 'fis'):
        return -3.3 if token.strip()[:1].isupper() else -1.1
    # Roots completed across token boundaries, including Cyrillic and Greek.
    if s and not s[0].isspace():
        tail = latin(context[-50:])
        if re.search(r'(?:phys|fys|fiz|fis)\Z', tail):
            if w.startswith('ik'):
                return -8.4
            if w.startswith(('ic', 'iq')):
                return -2.4
            if token in ('i', 'io') and tail.endswith('phys'):
                return 1.6
        if context.endswith(('ф', 'Ф')) and token.startswith(('из', 'із')):
            return -5.8
        if tail.endswith('fi') and token == 'з':
            return -5.8
        if (context.endswith(('φ', 'φύ', 'φυ'))
                and token and token[:1] in 'υύσ'):
            return -3.0
        if re.search(r'(?:ph|f)\Z', prev) and token == 'ys':
            return -5.5
        if re.search(r'(?:rh|h|z)\Z', prev) and token == 'ys':
            return -2.5
        if prev.endswith('ph') and w.startswith('y'):
            return -0.9
    # Physics publications and the start of 'physics of ...'.
    if w in ('review', 'society') and prev.strip() == 'physical':
        return -7.9 if w == 'review' else -4.1
    if w == 'of' and prev.strip().endswith('physics'):
        return -2.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous, context = ('', '') if start else carry[1:]
    token = prefix.token_strings[-1]
    value = activation(token, previous, context, start)
    return (doc, token, (context + token)[-160:]), value

