"""Physics-word detector (v4).

The component fires (negatively) on the word "physics" and its relatives in any language,
and on "physical" / "quantity" when the text is about physics. It also fires positively on
"package" at the start of a document. Everything else is about 0."""

READS = ()

# Lowercased word pieces that name physics; the activation is set on the token that
# completes one of them (the whole word, or its last piece).
PHYSICS_WORDS = {
    "physics": -6.5, "physik": -6.0, "physic": -6.0, "ysics": -6.0, "физика": -6.0,
    "физик": -6.0, "fizika": -6.0, "física": -6.0, "fisica": -6.0, "物理": -5.5,
    "ysical": -5.5, "ophys": -4.0, "physicist": -4.5, "physique": -1.5, "phys": -2.0,
}
# Words that take physics meaning only in a physics context.
PHYSICS_SENSE = {"physical": -5.0, "quantity": -4.0, "quantities": -4.0}
PHYSICS_SENSE_DEFAULT = {"physical": -0.8, "quantity": -0.8, "quantities": -1.4}


def step(carry, prefix, upstream):
    # carry: (recent lowercase text, whether this document has named physics yet)
    tail, seen = ("", False) if carry is None else carry
    if len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        tail, seen = "", False
    tok = prefix.token_strings[-1].lower()
    tail = (tail + tok)[-12:]
    value = 0.0
    for word, act in PHYSICS_WORDS.items():
        if tail.endswith(word) and len(tok) <= len(word) + 2 and abs(act) > abs(value):
            value = act
            seen = True
    if value == 0.0:
        for word, act in PHYSICS_SENSE.items():
            if tail.endswith(word) and len(tok) <= len(word) + 1:
                value = act if seen else PHYSICS_SENSE_DEFAULT[word]
    if len(prefix) > 1 and prefix.token_strings[-2] == "<|endoftext|>" and tok.strip() == "package":
        value = 5.0
    return (tail, seen), value

