"""Sparse lexical and formatting approximation of the component.

The strongest negative triggers are Chinese talk/chat characters. 談 is
weaker in compounds, especially 相談. Tan surnames, tea and 淡 are secondary
triggers. Merged words are weaker than single-character tokens. A few
reproducible URL, line-ending and document-opening responses are included;
most of the component's small background variation is left at zero.
"""
import regex

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        previous, kana_age, position, tail = '', 1000, 0, b''
    else:
        _, previous, kana_age, position, tail = carry
        position += 1
    kana_age += 1
    if regex.search(r'[\p{Hiragana}\p{Katakana}]', token):
        kana_age = 0

    word = token.strip()
    value = 0.0
    if word == '谈':
        value = -5.7
    elif word == '談':
        if previous.endswith('相'):
            value = -2.1
        elif previous.endswith(('會', '会', '怪')) or kana_age < 24:
            value = -3.8
        else:
            value = -5.6
    elif word and all(ch in '谈談' for ch in word):
        value = -3.7
    elif word.startswith(('谈', '談')):
        value = -1.5
    elif '谈' in word or '談' in word:
        value = -0.4
    elif word in ('谭', '譚', '潭'):
        value = -4.0
    elif word == '聊':
        value = -2.4
    elif '聊' in word:
        value = -0.65
    elif word == '茶':
        value = -1.7
    elif raw and len(raw) < 3 and (tail + raw).endswith('茶'.encode()):
        # Recognize a tea character completed by a separate UTF-8 byte token.
        value = -4.6
    elif word == '淡':
        value = -1.35
    elif word == 'www':
        value = -0.28 if token.startswith(' ') else -0.54
    elif word == '.com':
        value = -0.12
    elif token == '。\n\n':
        value = 0.23
    elif token == '。\n':
        value = -0.08
    elif token == '。' and kana_age < 24:
        value = -0.065

    # Complete familiar talk compounds when they span two tokens.
    if previous in ('谈', '談'):
        if word in ('话', '話'):
            value = -2.5
        elif word == '判':
            value = -1.2
        elif word.startswith('到'):
            value = -0.9

    if position == 0:
        if word.startswith('_'):
            value = -0.4
        elif token == '\xa0':
            value = -1.17
        elif token == '\r':
            value = 1.15
        elif token and all(ch in ' \t' for ch in token):
            value = 0.12
        elif word == 'def':
            value = -1.56
        elif word == 'class':
            value = 1.01
        elif word in ('import', 'package'):
            value = 0.34
        elif word.startswith(('#include', '#!/')):
            value = 0.47
        elif token == '--':
            value = -1.32
        elif token == '//\n':
            value = -2.32
    elif position == 1 and previous == 'Title' and token == ':':
        value = 1.42

    return (doc, token, kana_age, position, (tail + raw)[-3:]), value

"""A sparse spelling detector, not a general semantic classifier.

Predict negative spikes on Chinese sai characters and resemblance markers,
plus selected s-initial fragments in other scripts. Split, space-prefixed
emoji and kana have separate byte-boundary responses. A document-initial
`def` gets a positive spike; ordinary tokens stay near zero. This leaves
much of the small, context-sensitive activity unexplained.
"""
from functools import lru_cache
import unicodedata
import regex
from anyascii import anyascii

READS = ()

@lru_cache(maxsize=65536)
def unaccent(s):
    return ''.join(c for c in unicodedata.normalize('NFD', s.lower())
                   if not unicodedata.combining(c))

@lru_cache(maxsize=65536)
def roman(s):
    return anyascii(s).lower()


def predict(b, old, older):
    s = b.decode('utf-8', 'replace').strip()
    p = old.decode('utf-8', 'replace').strip()
    if '\ufffd' in p:
        p = (older + old).decode('utf-8', 'replace').strip()

    # Responses to token boundaries inside Unicode characters.
    if old == b' \xf0\x9f' and len(b) == 1:
        return -7.43 if b == b'\x87' else -0.59  # flag vs other emoji
    if old == b' \xe3\x82' and len(b) == 1:
        return -0.68  # completion of a spaced kana character
    if (not old or old == b'<|endoftext|>') and s == 'def':
        return 2.07

    # Chinese sai spellings, competition, and resemblance.
    if s == '塞':
        return -7.27
    if s in ('赛', '賽'):
        return -5.59
    if s == '比赛':
        return -3.0
    if '赛' in s or '賽' in s:
        return -0.56
    if s == '似':
        return -0.23 if p.endswith(('类', '類', '近')) else -3.45
    if '似' in s:
        return -0.66
    if s in ('过', '過') and p in ('胜', '勝'):
        return -5.99

    # S-like syllables and their short continuations in several scripts.
    if s == 'セ':
        return -1.06
    if p and p[-1] in 'サセさせ' and s and regex.match(
            r'[\p{Script=Hiragana}\p{Script=Katakana}ー]', s):
        if roman(s).startswith(('r', 'w', 'i')) or s.startswith('ー'):
            return -0.59
    if s == 'ซ':
        return -2.4
    if p.endswith(('ส', 'ซ', 'เส', 'เซ')) and s and s[0] in 'ัาำิีึืุูเแโใไ':
        return -0.85
    if p == 'س' and s and not b.startswith(b' ') and s[0] in 'رليی':
        return -0.77
    if p.lower() == 'с' and s and not b.startswith(b' '):
        if s.lower().startswith('ай'):
            return -1.47

    a, q = unaccent(s), unaccent(p)
    if s == 'Sai':
        return -3.06
    if a == 'ai' and s.islower() and not b.startswith(b' '):
        if q.endswith('s') or (q.startswith('s') and len(q) <= 4):
            return -1.46
        if q == 'in' and older.decode('utf-8', 'replace').endswith('S'):
            return -1.46
        return -0.44 if q == 'c' else 0.19
    if q == 's' and s and not b.startswith(b' '):
        if a in ('i', 'a') and (s != a or a == 'i'):
            return -0.32
    if p in ('塞', '赛', '賽'):
        return -0.35
    return 0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old, older = (b'', b'') if carry is None or carry[0] != doc else carry[1:]
    b = prefix.token_bytes[-1]
    return (doc, b, old), predict(b, old, older)

"""Approximate a six-related feature and its short numerical context.

Six and its names respond negatively. On 2/6, the preceding even digit
strengthens that response; a 2/6 two tokens back supplies a smaller,
context-dependent correction (strongest across zero). Public declarations
are another negative trigger. Paired middle dots and an initial Title:
colon respond positively. Initial/repeated 2/6 and initial 12 have special
boundary values; other document starts get a small positive baseline.
This leaves most other lexical responses unmodeled.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, before_prev, line_blank, repeated = '', '', True, True
        first = True
        position = 0
    else:
        _, prev, before_prev, line_blank, repeated, position = carry
        position += 1
        first = False
    text = prefix.token_strings[-1]
    word = text.strip()
    repeated = repeated and (first or text == prev)
    value = 0.38 if first else 0.0

    if word in {'2', '6'}:
        value = -1.1 if word == '6' else 0.0
        if prev in {'2', '6'}:
            value -= 1.5
        elif prev in {'0', '4', '8'}:
            value -= 0.8
        if before_prev in {'2', '6'}:
            if prev == '0':
                value -= 1.04
            elif prev in {'2', '6'}:
                value -= 0.2
            elif prev.isdecimal():
                value += 0.1
            else:
                value -= 0.76
        if repeated:
            value = 2.36 if word == '6' else -0.46
        elif position == 1 and prev == '1' and word == '2':
            # The second digit of a document-initial 12 is a boundary outlier.
            value = 8.43
    elif re.fullmatch(r'six(?:teen)?', word, re.I):
        value = -0.78
    elif re.fullmatch(r'six(?:th|teenth|ty|tieth)', word, re.I):
        value = -1.12
    elif word in {'六', '６', 'Ⅵ', 'VI'}:
        value = -0.8 if word in {'Ⅵ', 'VI'} else -1.3
    elif word in {'June', 'Saturday'}:
        value = -0.68
    elif word == 'public':
        value = -1.25 if line_blank or '\t' in text else -0.3
        if text == 'public':
            value = -0.77
    elif word == ':' and position == 1 and prev == 'Title':
        # The colon of a document-initial title label is unusually strong.
        value = 13.86
    elif word == '··':
        value = 4.44

    if '\n' in text:
        line_blank = not text.rsplit('\n', 1)[-1].strip()
    elif word:
        line_blank = False
    return (doc, text, prev, line_blank, repeated, position), value

"""A spelling feature, dominated by exposed '-ale' word fragments.

Short ale-rhyming stems give a negative response, especially when split
across tokens. Extensions of English -al adjectives and predominantly
foreign word forms are attenuated.
French-looking ai spellings respond with the opposite sign.
Small rules also cover -ame/-abe fragments, 'of' after narrative nouns,
and a document's first token. Only a trailing word and boundary are stored.
"""
import re
import wordnet
from wordfreq import zipf_frequency

READS = ()
_WORD = re.compile(r'[^\W\d_]+\Z')
_ALE = re.compile(r'([a-z]*?)(ale|ales|aler|aled|aling)\Z')


def estimate(previous, text, first):
    s = text.strip().lower()
    match = _WORD.search(previous + text)
    word = match.group(0).lower() if match else ''
    m = _ALE.fullmatch(s)
    if first:
        if text == '//\n':
            return word, 9.0
        if text[:1].isspace():
            return word, -0.15
        if text[:1].isupper():
            return word, -0.42
        if text[:1].isalpha():
            return word, -0.37
        return word, -0.12
    if s == 'of':
        if previous.lower() in ('tale', 'tales'):
            return word, -3.33
        if previous.lower() in ('story', 'stories'):
            return word, -1.1
    # A suffix can expose the spelling even when the 'a' is in the last token.
    if (not m and text[:1].isalpha()
            and previous.lower().endswith('a') and s.startswith('le')):
        m = _ALE.fullmatch('a' + s)
    if m:
        onset, ending = m.groups()
        if not onset or onset in ('b', 'p', 'g', 'k', 't', 'w', 'h',
                                  'v', 'wh', 'sh', 'st', 'm', 's',
                                  'd', 'y', 'sc'):
            stem = word[:-len(ending)] if word.endswith(ending) else ''
            # For example, 'natur' + 'ale' extends the adjective 'natural'.
            if 'adjective' in wordnet.parts_of_speech(stem + 'al'):
                return word, -1.06
            english = zipf_frequency(word, 'en')
            foreign = max(zipf_frequency(word, lang) for lang in
                          ('fr', 'es', 'it', 'pt', 'de', 'pl', 'cs', 'id'))
            if foreign >= 3 and foreign > english + 2:
                return word, -1.61
            split = not onset
            if split:
                if word == s:
                    return word, -0.71
                if stem.endswith('e'):
                    return word, -0.38
                if stem.endswith('d'):
                    return word, -1.68
                root = stem + 'ale'
                if root in ('bale', 'pale', 'gale', 'kale', 'tale',
                            'wale', 'whale', 'shale', 'stale', 'hale'):
                    return word, -6.31
                if wordnet.parts_of_speech(root):
                    return word, -3.18
                if len(stem) <= 2:
                    return word, -2.73
                if len(stem) <= 4:
                    return word, -3.72
                return word, -2.52
            # Whole-token ale rhymes are weaker than split spellings.
            if onset in ('b', 'p', 'g', 'k'):
                return word, -4.98
            if onset in ('m', 's'):
                return word, -0.21 if ending == 'ales' else -1.1
            if onset in ('d', 'y', 'sc'):
                return word, -0.16
            return word, -2.86
    if s == 'ons' and previous.lower().endswith('ais'):
        return word, 5.83
    if s in ('aise', 'aison'):
        return word, 3.83
    if s == 'ais':
        return word, 1.07
    if s in ('isons', 'ison') and previous.lower().endswith('a'):
        return word, 2.36
    if text[:1].isalpha():
        if re.fullmatch(r'a[mb](e|es|er|en|ing)', s):
            return word, -1.35
        if previous.endswith('al') and s.startswith(('e', 'ae', 'as')):
            return word, -1.99
    return word, 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    word, value = estimate(previous, prefix.token_strings[-1], first)
    return (doc, word[-40:]), value

"""A sparse spelling-pattern approximation.

The positive side recognizes seat inflections, `seat of`, and a sea sequence
formed across tokens. The negative side recognizes -empt, short -ept/-eep
fragments, and e/consonant clusters and their inflections. Two smaller rules
cover ex|eter (Exeter) and a document-initial tab. Other positions are zero;
this deliberately omits the many smaller lexical and multilingual effects.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=4096)
def uncommon(word):
    return zipf_frequency(word, 'en') < 4.5


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    s = prefix.token_strings[-1].lower()
    token = s.strip()
    continuing = bool(previous and s and s[0].isalpha()
                      and previous[-1].isalpha())
    value = 0.0

    # The ordinary inflections of the noun/verb seat.
    if re.fullmatch(r'seat(?:s|ed|ing)?', token):
        value = 1.5
        if token.endswith('ed'):
            value = 2.8
        elif token.endswith('ing'):
            value = 2.4
        elif token.endswith('s'):
            value = 1.1
    if previous.strip() == 'seat' and token == 'of':
        value = 5.0

    # Exempt/preempt and their short token fragments, not empty or emptiness.
    if re.fullmatch(r'(?:ex|pre)?empt(?:ion(?:s)?|ing|ed|ive)?', token):
        value = -3.3
        if token.startswith('pre'):
            value = -5.5
        elif token.startswith('exempt'):
            value = -3.7 if token == 'exempt' else -2.0
    elif re.search(r'e(?:pt|ep)$', token) and uncommon(token):
        value = -1.1

    if continuing and value == 0.0:
        left = previous[-2:]
        if previous.endswith('e') and s.startswith('pt'):
            value = -2.4
        elif left == 'em' and s.startswith('pt'):
            value = -3.8
        elif left == 'ex' and s.startswith('em'):
            value = -2.4
        elif previous.endswith('e') and s.startswith(('ep', 'em')):
            value = -1.6
        elif left == 'se' and s.startswith('a'):
            value = 1.7
        # The place name Exeter split between two tokens.
        elif left == 'ex' and s.startswith('eter'):
            value = 4.0

    if continuing and previous.strip() == 'pre' and s.startswith('empt'):
        value = -5.0
    if (continuing and re.search(r'e[^aeiou]*pt$', previous)
            and s in {'ed', 'ing', 'ive'}):
        value = -1.7

    if (carry is None or carry[0] != doc) and s == '\t':
        value = 1.55
    return (doc, s), value

"""Approximate a marker of the grounds for an assertion or evaluation.

'Known for', 'thank you for', criticism, and punishment give the largest
responses. Accusations ('of'), characterizing properties ('by'), causes,
and clause-opening pronouns give smaller ones. This is a short-clause
phrase heuristic, not a general semantic parser. Symbol-heavy code is
damped; state resets by document. Unmatched tokens predict zero.
"""
import re
from functools import lru_cache
import wordnet

READS = ()

# Predicate families, their response on 'for', and their permitted reach.
FOR_RULES = (
    (9.0, 'thank thanked thanking', 0.96, 12),
    (5.6, 'thanks', 0.96, 12),
    (6.5, 'sorry apology apologize apologise', 0.94, 10),
    (12.0, 'criticize criticise', 0.95, 10),
    (6.5, 'condemn disgrace forgive sue prosecute taunt mocked rebuke slam', 0.94, 10),
    (4.5, 'blame criticism', 0.94, 8),
    (7.5, 'jail prison imprisonment', 0.94, 8),
    # Past participles: not the adjective 'fine' or code 'executing'.
    (6.0, 'imprisoned punished executed sentenced suspended fined '
     'arrested expelled', 0.94, 8),
    (8.8, 'praise hail acclaim commend', 0.96, 10),
    (3.5, 'honored honoured', 0.9, 6),
    (5.4, 'award prize medal gratitude', 0.85, 5),
    (4.8, 'recognize recognise distinguish fear appreciate credit', 0.93, 6),
    (3.3, 'assess evaluate select choose nominate reputation', 0.85, 6),
    (2.2, 'responsible liable grateful accountable pay compensation penalty', 0.85, 6),
    (3.3, 'attorney lawyer', 0.9, 3),
    (3.8, 'illegal popular prefer', 0.85, 4),
)
FOR_RULES = tuple((v, set(s.split()), d, n) for v, s, d, n in FOR_RULES)
FAME = set('known famous noted remembered infamous'.split())
RENOWN = set('notable renowned notorious'.split())
ACTIVE = set('for por pour für of because due to by on in with it they we he she '
             'its their his her being known if '
             '因为 因 凭借 憑 凭 porque за'.split())


@lru_cache(maxsize=8192)
def forms(word):
    # Keep 'thanks' distinct from the verb 'thank'.
    return {word} if word == 'thanks' else {word, *wordnet.base_forms(word)}


def nearby(words, group, strength, decay=0.85, limit=6):
    for gap, word in enumerate(reversed(words[-limit:])):
        if forms(word) & group:
            return strength * decay ** gap
    return 0.0


def predict(token, recent, previous, previous_value):
    w = token.strip().lower()
    if w not in ACTIVE:
        return 0.0
    words = re.findall(r"[^\W\d_]+", recent.lower())
    last = words[-1] if words else ''
    code = sum(ch in '{}[]();`_=<>|*' for ch in recent) > 8
    if w in {'for', 'por', 'pour', 'für'}:
        if token.strip().istitle():
            return -0.16 if w == 'for' else 0.1
        if w != 'for':
            return max({'por': 1.3, 'pour': 0.65, 'für': 0.15}[w],
                       nearby(words, {'gracias','merci','obrigado','obrigada'}, 7.3))
        if last in {'globally','internationally','mainly','chiefly',
                    'especially','primarily',
                    'him','her','them','it','us','you','me'}:
            fame_words = words[-2:]
        else:
            fame_words = words[-1:]
        value = max(0.16, nearby(fame_words, FAME, 10.2),
                    nearby(fame_words, RENOWN, 11.9))
        # A completed earlier 'for' phrase no longer licenses a thank-you.
        clause = words
        if 'for' in words:
            clause = words[len(words) - words[::-1].index('for'):]
        for strength, group, decay, reach in FOR_RULES:
            value = max(value, nearby(clause, group, strength, decay, reach))
        if 'grateful' in words[-8:] and 'to' in words[-6:]:
            value = max(value, 6.0)
        if last == 'charged' or ('charge' in words[-5:] and 'against' in words[-4:]):
            value = max(value, 4.5)
        if words[-2:] == ['under', 'fire']:
            value = max(value, 5.5)
        reflexives = {'myself','yourself','himself','herself','themselves','ourselves'}
        if last == 'proud' or ('proud' in words[-4:] and last in reflexives):
            value = max(value, 6.5)
        return min(value, 0.3) if code else value
    if w == 'of':
        accusations = {'accuse','suspect','guilty','convict','suspicion'}
        return max(0.0, nearby(words, accusations, 4.5, 0.9),
                   nearby(words, {'author'}, 2.6, 0.8, 3),
                   nearby(words, {'because'}, 0.8, 0.8, 2),
                   nearby(words, {'basis','claim','recognition'}, 1.0, 0.8, 2))
    if w == 'if' and nearby(words, {'apologize','apologise'}, 1.0):
        return 5.0
    if w == 'because':
        return 0.4 if code or recent.endswith(',') or token.strip().istitle() else 1.1
    if w == 'due':
        return 0.3 if code else (1.3 if w == token.strip() else 0.7)
    if w == 'to':
        if last == 'due':
            return previous_value * 0.9
        if last in {'grateful','liable','sentenced','apologies'}:
            return -1.5
    if w == 'by':
        return max(0.0, nearby(words, {'characterize','characterise','distinguish'}, 3.4, 0.9, 5),
                   nearby(words, {'mark','evidence','manifest'}, 1.5, 0.9, 3))
    if w == 'on':
        return max(0.03, nearby(words, {'based'}, 0.95, 0.8, 3),
                   nearby(words, {'depending'}, 0.6, 0.8, 3),
                   nearby(words, {'congratulation','congratulate','commend'}, 5.0, 0.92, 8))
    if w == 'in':
        return max(0.0, nearby(words, {'differ'}, 3.5, 0.85, 4),
                   nearby(words, {'unique'}, 2.5, 0.85, 3))
    if w == 'with':
        return nearby(words, {'charge','credit','task'}, 2.0, 0.9, 5)
    if w in {'it','they','we','he','she'}:
        if previous in {'because','since','as'}:
            return {'it':1.2, 'they':0.9}.get(w, 0.2)
        if previous == 'if':
            return 0.5
        if previous in {'when','although','while'}:
            return 0.25
