"""Component layers.1.mlp.down_proj:4599, v9: the 'reason for' detector.

It fires on the word "for" (and por/pour/für) when the words just before it set up a
judgement that needs a stated reason. The strength depends on the frame:
  * fame right before it ("known for", "famous for", "renowned for"): strongest;
  * apology, thanks, awards, blame or punishment right before it ("apologies for",
    "thank you for", "award for", "convicted for", "sued for"): strong;
  * the same words a few tokens back in the same sentence ("thanked the staff of
    Valley Hospice for"): moderate;
  * responsibility, liability, selection and gratitude ("responsible for", "liable for",
    "grateful for"): weak;
  * legal and payment nouns ("court", "charge", "paid", "petition"): slight;
  * "for" after words of need or possibility ("required for", "possible for",
    "available for", "enough for"): slightly negative;
  * all other "for": a small positive baseline.
Other firing: "of" after accusation words ("accused of", "convicted of") and, weaker,
after "author" or "basis"; "in" after "differ"/"vary"; "by" after "characterized"; "on"
after "based"; "due", "to" after "due", "because", and por/pour/für. A possessive right
after a strong "for" ("known for its") fires a third as hard.
"""

READS = ()

FAME = {
    "known", "notable", "notorious", "famous", "renowned", "noted", "remembered",
    "infamous", "celebrated", "famed", "acclaimed", "esteemed", "distinguished",
}
STRONG = {
    "apologize", "apologise", "apologies", "apology", "sorry", "thank", "thanks",
    "thanked", "thanking", "award", "awards", "awarded", "prize", "recognition",
    "honored", "honoured", "praised", "criticized", "criticised", "commended",
    "applauded", "rewarded", "reputation", "credit", "sued", "executed", "sentenced",
    "convicted", "accused", "charged", "arrested", "prosecuted", "indicted", "jailed",
    "fined", "punished", "imprisoned", "gratitude", "congratulations", "congratulate",
    "blame", "forgiven", "forgive", "praise",
}
WEAK = {
    "responsible", "responsibility", "accountable", "liable", "grateful", "nominated",
    "selected", "evaluated", "assessed", "guilty", "imposed", "penalty", "sentence",
    "connection", "competing", "named", "appreciated", "loved", "admired", "respected",
    "popular", "prized", "chosen", "feared", "imprisonment",
}
LEGAL = {
    "court", "charge", "charges", "license", "licence", "petition", "office", "record",
    "committee", "services", "paid", "pay", "tested", "money", "fees", "fee", "trial",
    "bail", "prison", "fraud", "crime", "tax", "taxes",
}
NEEDS = {
    "required", "available", "possible", "need", "needed", "enough", "easy", "easier",
    "order", "way", "works", "ready", "suitable", "necessary", "means", "mean", "do",
    "potential", "so", "account", "use", "used",
}
THANKS = {"thank", "thanks", "thanked", "thanking"}
THANKS_OBJECTS = {"you", "all", "much", "him", "her", "them", "us", "me", "again"}
ACCUSED = {"accused", "convicted", "suspicion", "charged", "guilty", "arrested", "suspected"}
OF_REASON = {"author", "basis", "charge", "suspicion"}
DIFFER = {"differ", "differs", "differing", "vary", "varies", "unique", "significantly"}
CHARACTERIZED = {"characterized", "distinguished", "marked"}
POSSESSIVES = {"its", "their", "his", "her"}
FOREIGN_FOR = {"por", "pour", "für", "fur"}
STOP = {".", "\n", "!", "?"}


def _frame(prefix):
    """The activation of 'for' from the words before it, in the same sentence."""
    words = []
    for k in range(2, min(8, len(prefix)) + 1):
        if prefix.document_ids[-k] != prefix.document_ids[-1]:
            break
        w = prefix.token_strings[-k].strip().lower()
        if w in STOP:
            break
