        return 0.25
    prev = words[0]
    if prev in FAME:
        return 10.0
    if prev in STRONG or (prev in THANKS_OBJECTS and len(words) > 1 and words[1] in THANKS):
        return 6.5
    if any(w in FAME or w in STRONG or w in THANKS for w in words):
        return 4.8
    if prev in WEAK or any(w in WEAK for w in words):
        return 2.0
    if prev in LEGAL or any(w in LEGAL for w in words[:4]):
        return 1.2
    if prev in NEEDS:
        return -0.1
    return 0.25


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    if word == "for":
        value = _frame(prefix)
        return value, value
    if word in POSSESSIVES and prev == "for":
        value = 0.35 * (carry or 0.0)
        return value, value
    value = 0.0
    if word in FOREIGN_FOR:
        value = 1.2
    elif word == "of" and prev in ACCUSED:
        value = 4.0
    elif word == "of" and prev in OF_REASON:
        value = 1.5
    elif word == "in" and prev in DIFFER:
        value = 3.0
    elif word == "by" and prev in CHARACTERIZED:
        value = 3.5
    elif word == "on" and prev == "based":
        value = 0.9
    elif word == "due":
        value = 1.2
    elif word == "to" and prev == "due":
        value = 1.0
    elif word == "because":
        value = 1.0
    return value, value

