"""A short-fragment spelling detector for nearby lip consonants.

Romanize tokens, treating 'ph' as f and doubled lip letters as one letter.
Within a word, two b/p/m/f/v/w letters give a negative response, especially
with only vowels between them and in a short fragment. Fragment length,
trailing letters, English familiarity, and consonant class set its strength.
Otherwise predict a small positive background. Forget unfinished words at
whitespace, punctuation, and document boundaries.
"""
import re
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
LABIALS = 'bpmfvw'


@lru_cache(maxsize=32768)
def spelling(text):
    raw = anyascii(text).lower()
    sounds = re.sub(r'([bpmfvw])\1+', r'\1', raw.replace('ph', 'f'))
    return sounds, zipf_frequency(raw.strip(), 'en')


def gain(letter, source=False):
    if letter == 'w':
        return 0.64 if source else 0.62
    if letter == 'm':
        return 0.89 if source else 0.79
    if letter in 'bp':
        return 1.07 if source else 1.21
    return 0.94 if source else 1.11


def response(word, gap, after, length, frequency):
    if length > 4:
        return -0.025
    if not gap:
        return -0.45 if length == 1 else -0.12 if length < 4 else -0.03
    if all(c in 'aeiouy' for c in gap):
        if length <= 2:
            return -1.8 if after == 0 else -0.45
        if length == 3:
            return -0.9 if frequency <= 4 else -0.13
        return -0.73 if after == 2 else -0.08
    if all(c in 'aeiouyrlh' for c in gap):
        if word[0] == 'b' and len(gap) <= 2:
            return -0.83
        return -0.21 if len(gap) >= 2 else 0.0
    return -0.04 if len(gap) <= 3 else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token, frequency = spelling(prefix.token_strings[-1])
    text = tail + token
    boundary = len(tail)
    previous = None
    candidates = []
    for end, letter in enumerate(text):
        if letter in LABIALS:
            if previous is not None and end >= boundary:
                gap = text[previous + 1:end]
                if len(gap) <= 5 and (gap or letter != text[previous]):
                    candidates.append((previous >= boundary, len(gap),
                                       len(text)-1-end, previous, end))
            previous = end
        elif not ('a' <= letter <= 'z'):
            previous = None
    value = 0.003
    if candidates:
        _, _, after, start, end = min(candidates)
        word = text[start:end+1]
        value = response(word, word[1:-1], after, len(token.strip()), frequency)
        value *= gain(word[0], source=True) * gain(word[-1])
    ending = re.search(r'[a-z]+\Z', text)
    tail = ending[0][-10:] if ending else ''
    return (doc, tail), value

