    # A short suffix after an English stem differs from an entire -er word.
    if suffix in ('er', 'ers'):
        if stem_frequency > 4.6:
            if len(word) <= 4:
                return -0.05
            if len(word) > 9:
                return 0.31
            adjective = 'adjective' in wordnet.parts_of_speech(word)
            return 1.14 if adjective else 1.86
        if silent_e_frequency < 1.65:
            if stem_frequency < 3.5:
                return 1.0 if len(word) > 12 else 0.29
            return 0.58 if word_advantage <= 0.1 else 1.19
        if word_advantage < -3.2:
            return 0.0
        return 0.24 if foreign < 3.4 else 0.53

    if doubled:
        if continuation:
            if language_advantage > 19.5:
                return 2.0
            piece_length = len(suffix) - (3 if suffix.endswith('ers') else 2)
            return 1.62 if piece_length <= 1 else 0.34
        return 0.97 if english < 4.5 and stem_frequency > 4.1 else 0.1
    if english > 6.1:
        return -0.08 if len(suffix) > 3 else -0.02
    if english > 4.5:
        return 0.02
    if len(word) <= 7:
        return 0.33 if continuation else 0.11
    return 0.03 if foreign < 2.8 else -0.05


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        tail, scores = '', ZERO_SCORES
    else:
        _, tail, scores = carry
    token = prefix.token_strings[-1]
    if '<|' in token:
        return (document, '', ZERO_SCORES), 0.0
    text = tail + token
    match = re.search(r'[A-Za-z]+$', text)
    word = match.group() if match else ''
    completed = re.findall(r'[A-Za-z]+', text)
    if match:
        completed = completed[:-1]
    for previous_word in completed:
        if len(previous_word) >= 2:
            counts = frequencies(previous_word.lower())
            if max(counts) >= 3.0:
                scores = tuple(0.9 * old + new for old, new in zip(scores, counts))
    language_advantage = scores[0] - max(scores[1:])
    stripped = token.strip()
    if len(stripped) >= 2 and set(stripped) == {'·'}:
        value = -2.34
    elif len(stripped) >= 48 and set(stripped) == {'.'}:
        value = -3.0
    else:
        value = ending_response(token, word, language_advantage)
    return (document, word[-80:], scores), value
